// Упражнения в тетрадь главы «Деепричастие». n — постоянный номер: не менять и не переиспользовать.
// Классика — дословно (ё восстановлена), с подписью; бережные сокращения отмечены «…».
// Спорное (одиночное деепричастие после сказуемого, брать/тянуть/спать, двоякие формы) — только в ★★★★★ с пометкой «тонкость».
// План морфологического разбора — по Н. Адамчику (урок 6 теории).
const DR_CLASSIC=[
// ── Урок 1. Что такое деепричастие
 {n:1,l:1,st:1,task:'Выписать деепричастия вместе с глаголами-сказуемыми, к которым они относятся. Поставить от сказуемого вопрос «что делая?» или «что сделав?». Деепричастие подчеркнуть как обстоятельство (точка — тире).',
  obr:'Улыбаясь, Галя открыла ворота. → Открыла (что делая?) улыбаясь.',
  body:'1. Собака бежала впереди, весело виляя хвостом. 2. Закончив уроки, Таня вышла во двор. 3. Лесник, надев очки, развернул газету. 4. Школьники шли по бору, собирая грибы и перекликаясь. 5. Проснувшись рано утром, я долго смотрел в окошко. 6. Мы сидели у костра, слушая треск сучьев. 7. Котик, испугавшись пылесоса, спрятался под диван. 8. Отдохнув, путники двинулись дальше. 9. Река текла среди лугов, извиваясь и поблёскивая на солнышке. 10. Попрощавшись с друзьями, Миша сел в троллейбус.',
  key:'1. Бежала (что делая?) виляя. 2. Вышла (что сделав?) закончив. 3. Развернул (что сделав?) надев. 4. Шли (что делая?) собирая и перекликаясь — два деепричастия при одном сказуемом. 5. Смотрел (что сделав?) проснувшись. 6. Сидели (что делая?) слушая. 7. Спрятался (что сделав?) испугавшись. 8. Двинулись (что сделав?) отдохнув. 9. Текла (что делая?) извиваясь и поблёскивая. 10. Сел (что сделав?) попрощавшись.'},
 {n:2,l:1,st:1,task:'Распределить деепричастия в два столбика: отвечающие на вопрос «что делая?» и отвечающие на вопрос «что сделав?». Рядом с каждым записать глагол, от которого оно образовано, и указать вид глагола.',
  obr:'Купаясь — что делая? — купаться (несов. в.); искупавшись — что сделав? — искупаться (сов. в.).',
  body:'Рассматривая, догнав, решив, оглядываясь, бросив, ныряя, собрав, встречая, вздохнув, рассмотрев, догоняя, решая, оглянувшись, бросая, нырнув, собирая, встретив, вздыхая.',
  key:'Что делая? (несов. в.): рассматривая — рассматривать; оглядываясь — оглядываться; ныряя — нырять; встречая — встречать; догоняя — догонять; решая — решать; бросая — бросать; собирая — собирать; вздыхая — вздыхать.<br>Что сделав? (сов. в.): догнав — догнать; решив — решить; бросив — бросить; собрав — собрать; вздохнув — вздохнуть; рассмотрев — рассмотреть; оглянувшись — оглянуться; нырнув — нырнуть; встретив — встретить.<br>Вид деепричастия всегда тот же, что у глагола, от которого оно образовано.'},
 {n:3,l:1,st:2,task:'Распределить сочетания в три столбика: с глаголом-сказуемым, с причастием, с деепричастием. Поставить вопрос к выделенной форме. Объяснить, чем причастие отличается от деепричастия того же глагола.',
  obr:'Тает на солнышке (что делает?) — глагол; тающий на солнышке снег (какой?) — причастие; тая на солнышке (что делая?) — деепричастие.',
  body:'Снег тает на солнышке; тающий на солнышке снег; лёд, растаявший к утру; растаяв к утру; шелестя страницами; шелестящая страница; камыш шелестит; выглянуло из-за туч; выглянув из-за туч; выглянувшее из-за туч солнышко; зевающий Васька; зевая во весь рот; Васька зевнул; обернувшись на шум; обернувшийся на шум прохожий; прохожий обернулся.',
  key:'Глагол: тает (что делает?), шелестит (что делает?), выглянуло (что сделало?), зевнул (что сделал?), обернулся (что сделал?).<br>Причастие: тающий (какой? что делающий?), растаявший (какой? что сделавший?), шелестящая (какая?), выглянувшее (какое?), зевающий (какой?), обернувшийся (какой?).<br>Деепричастие: растаяв (что сделав?), шелестя (что делая?), выглянув (что сделав?), зевая (что делая?), обернувшись (что сделав?).<br>Причастие называет признак предмета и изменяется (тающий, тающая, тающего), деепричастие называет добавочное действие при глаголе и не изменяется.'},
 {n:4,l:1,st:2,task:'Заменить деепричастие однородным сказуемым. Записать оба предложения и сравнить: какое действие в предложении с деепричастием главное, а какое — добавочное?',
  obr:'Рома шёл по улице, насвистывая песенку. → Рома шёл по улице и насвистывал песенку. Главное — шёл, добавочное — насвистывая; во втором предложении оба действия равноправны.',
  body:'1. Соседка сидела у окошка, читая статью. 2. Вернувшись из школы, Аня сразу села обедать. 3. Ветер раскачивал деревья, срывая с них листья. 4. Выслушав задание, ученики принялись за работу. 5. Тузик лежал на коврике, играя с мячиком. 6. Посмотрев на часы, Юля заторопилась. 7. Решив загадку, Федя пошёл гулять. 8. Чайки кружили над морем, громко крича.',
  key:'1. Соседка сидела у окошка и читала статью. 2. Аня вернулась из школы и сразу села обедать. 3. Ветер раскачивал деревья и срывал с них листья. 4. Ученики выслушали задание и принялись за работу. 5. Тузик лежал на коврике и играл с мячиком. 6. Юля посмотрела на часы и заторопилась. 7. Федя решил загадку и пошёл гулять. 8. Чайки кружили над морем и громко кричали.<br>В предложениях с деепричастием главное действие выражено сказуемым (сидела, села, раскачивал, принялись, лежал, заторопилась, пошёл, кружили), добавочное — деепричастием. Если деепричастие совершенного вида (вернувшись, выслушав, посмотрев, решив), при замене первым ставится сказуемое, которое было деепричастием: сначала выслушали, потом принялись.'},
 {n:5,l:1,st:2,task:'Определить вид деепричастий. Указать, происходит ли добавочное действие одновременно с главным или раньше него. Ответ записать так: «деепричастие — вид — одновременно / раньше».',
  obr:'Прочитав письмо, Анна Петровна улыбнулась. → Прочитав — сов. в. — раньше (сначала прочитала, потом улыбнулась).',
  body:'1. Слушая сказку, Тимоша крепко держал Мадину за руку. 2. Выглянув в окошко, Рита увидела первый снег. 3. Повар, пробуя суп, добавлял в него соль. 4. Спрятав ключ под коврик, мы ушли на прогулку. 5. Поезд мчался по степи, оглашая её гудками. 6. Натянув палатку, путешественники стали разводить костёр. 7. Шагая по лужам, мальчишки громко смеялись. 8. Наточив карандаш, художник начал рисовать.',
  key:'1. Слушая — несов. в. — одновременно. 2. Выглянув — сов. в. — раньше. 3. Пробуя — несов. в. — одновременно. 4. Спрятав — сов. в. — раньше. 5. Оглашая — несов. в. — одновременно. 6. Натянув — сов. в. — раньше. 7. Шагая — несов. в. — одновременно. 8. Наточив — сов. в. — раньше.<br>Несовершенный вид обычно показывает действие, которое идёт одновременно с главным; совершенный — действие, которое закончилось раньше.'},
 {n:6,l:1,st:2,task:'Доказать, что деепричастие не изменяется. Переписать предложения, изменив сказуемое: 1) по временам (настоящее, прошедшее, будущее); 2) по числам (подлежащее поставить во множественное число). Деепричастие оставить без изменений и подчеркнуть.',
  obr:'Читая, он улыбается. → Читая, он улыбался. Читая, он будет улыбаться. Читая, они улыбаются.',
  body:'1. Возвращаясь в деревню, Света заходит в булочную. 2. Наклонившись к цветку, Лиза рассматривает пчелу. 3. Собираясь в дорогу, Стёпа проверяет рюкзак. 4. Разбежавшись, спортсмен прыгает через планку.',
  key:'1. Возвращаясь в деревню, Света заходила / зайдёт (будет заходить) в булочную. Возвращаясь в деревню, сёстры заходят в булочную. 2. Наклонившись к цветку, Лиза рассматривала / будет рассматривать пчелу. Наклонившись к цветку, девочки рассматривают пчелу. 3. Собираясь в дорогу, Стёпа проверял / будет проверять рюкзак. Собираясь в дорогу, братья проверяют рюкзаки. 4. Разбежавшись, спортсмен прыгал / прыгнет (будет прыгать) через планку. Разбежавшись, спортсмены прыгают через планку.<br>Сказуемое меняет время и число, а деепричастия (возвращаясь, наклонившись, собираясь, разбежавшись) остаются теми же: деепричастие не изменяется, как наречие.'},
 {n:7,l:1,st:3,task:'Выписать деепричастия вместе со сказуемыми, к которым они относятся, указать вид деепричастия. Найти предложения, в которых деепричастие стоит после сказуемого, и предложение, в котором при одном сказуемом три деепричастия.',
  obr:'Лодка, плавно качаясь, быстро скользила… → Скользила (что делая?) качаясь — несов. в.',
  body:'1. Лодка, плавно качаясь, быстро скользила по тёмным волнам. (А. С. Пушкин, «Капитанская дочка») 2. Однажды, скитаясь с Ермолаем по полям за куропатками, завидел я в стороне заброшенный сад и отправился туда. (И. С. Тургенев, «Записки охотника») 3. Зевая, почёсываясь и укоризненно причмокивая языком, Ибрагим отпер двери. (А. И. Куприн, «Белый пудель») 4. Наигравшись, волчата пошли в яму и легли спать. (А. П. Чехов, «Белолобый») 5. Лукашка понимал её и всё кивал, слегка улыбаясь. (Л. Н. Толстой, «Казаки») 6. Лодыжкин, кряхтя, вскинул шарманку за плечи. (А. И. Куприн, «Белый пудель») 7. Тётка, не вынося музыки, беспокойно задвигалась на стуле и завыла. (А. П. Чехов, «Каштанка») 8. На другой день поутру, хорошенько выспавшись под одним пологом с милой моей сестрицей, мы встали бодры и веселы. (С. Т. Аксаков, «Детские годы Багрова-внука»)<br>Пояснения: шарманка — переносной музыкальный инструмент с ручкой; полог — занавес над кроватью.',
  key:'1. Скользила (что делая?) качаясь — несов. в. 2. Завидел (что делая?) скитаясь — несов. в. 3. Отпер (что делая?) зевая, почёсываясь, причмокивая — несов. в.; здесь при одном сказуемом три деепричастия. 4. Пошли (что сделав?) наигравшись — сов. в. 5. Кивал (что делая?) улыбаясь — несов. в.; деепричастие после сказуемого. 6. Вскинул (что делая?) кряхтя — несов. в. 7. Задвигалась и завыла (что делая?) не вынося — несов. в.; деепричастие относится к двум сказуемым. 8. Встали (что сделав?) выспавшись — сов. в.'},
 {n:8,l:1,st:3,task:'Прочитать отрывки из стихотворений. Выписать деепричастия вместе с глаголами, к которым они относятся. Указать вид. Объяснить, что добавляет деепричастие к картине, которую рисует поэт.',
  obr:'Буря мглою небо кроет, / Вихри снежные крутя… → Кроет (что делая?) крутя — несов. в.: буря одновременно кроет небо и крутит вихри.',
  body:'1. Буря мглою небо кроет, / Вихри снежные крутя; / То, как зверь, она завоет, / То заплачет, как дитя. (А. С. Пушкин, «Зимний вечер») 2. Ночевала тучка золотая / На груди утёса-великана; / Утром в путь она умчалась рано, / По лазури весело играя. (М. Ю. Лермонтов, «Утёс») 3. Скользя по утреннему снегу, / Друг милый, предадимся бегу / Нетерпеливого коня… (А. С. Пушкин, «Зимнее утро») 4. Уж расходились хороводы; / Уж за рекой, дымясь, пылал / Огонь рыбачий. (А. С. Пушкин, «Евгений Онегин») 5. Елисей, не унывая, / К ветру кинулся, взывая… (А. С. Пушкин, «Сказка о мёртвой царевне и о семи богатырях») 6. Там, где горы, убегая, / В светлой тянутся дали, / Пресловутого Дуная / Льются вечные струи… (Ф. И. Тютчев)<br>Пояснения: лазурь — голубизна неба; взывать — громко звать; пресловутый — здесь: всем известный.',
  key:'1. Кроет (что делая?) крутя — несов. в. 2. Умчалась (что делая?) играя — несов. в. 3. Предадимся (что делая?) скользя — несов. в. 4. Пылал (что делая?) дымясь — несов. в. 5. Кинулся (что делая?) не унывая, взывая — несов. в. 6. Тянутся (что делая?) убегая — несов. в.<br>Все деепричастия несовершенного вида: добавочное действие идёт одновременно с главным, и картина становится подвижной — буря не только кроет небо, но и крутит вихри, тучка не просто умчалась, а умчалась играя.'},
 {n:9,l:1,st:4,task:'Выписать в три столбика глаголы-сказуемые, причастия и деепричастия. Рядом с причастием записать определяемое слово, рядом с деепричастием — глагол, к которому оно относится. Какой признак помог отличить причастие от деепричастия?',
  obr:'Запыхавшись, он быстро скинул смеющуюся девочку… → Сказуемое: скинул; причастие: смеющуюся (девочку); деепричастие: запыхавшись (скинул).',
  body:'1. Запыхавшись, он быстро скинул смеющуюся девочку и прижал её к груди. (Л. Н. Толстой, «Война и мир») 2. Тётка проснулась, вскочила и, не сходя с матрасика, залилась поющим лаем. (А. П. Чехов, «Каштанка») 3. Пройдя по двору, он заметил отворённую дверь в хозяйской избушке и видневшуюся из неё голубую рубаху. (Л. Н. Толстой, «Казаки») 4. Впереди, уже далеко отделившись и звеня удаляющимся густым колокольцом, ясно виднелась на белом снегу чёрная тройка Захара. (Л. Н. Толстой, «Война и мир») 5. Бледный, встревоженный хозяин, вздыхая и покачивая головой, вернулся к себе в спальню. (А. П. Чехов, «Каштанка»)<br>Пояснения: колоколец (колокольцом — твор. п.) — колокольчик под дугой упряжки; тройка — упряжка из трёх лошадей.',
  key:'Сказуемые: скинул, прижал; проснулась, вскочила, залилась; заметил; виднелась; вернулся.<br>Причастия: смеющуюся (девочку); поющим (лаем); отворённую (дверь), видневшуюся (рубаху); удаляющимся (колокольцом); встревоженный (хозяин).<br>Деепричастия: запыхавшись (скинул); не сходя (залилась); пройдя (заметил); отделившись, звеня (виднелась); вздыхая, покачивая (вернулся).<br>Причастие отвечает на вопрос «какой?» и согласуется с существительным в роде, числе и падеже (смеющуюся девочку, поющим лаем), деепричастие отвечает на вопрос «что делая? что сделав?», относится к глаголу и не изменяется.'},
 {n:10,l:1,st:3,task:'Составить с каждым глаголом три предложения: в первом глагол — сказуемое, во втором — причастие, в третьем — деепричастие. Поставить вопросы к этим формам, деепричастие подчеркнуть как обстоятельство. Запятые поставить так, как в образце: оборот отделяется запятыми (подробно — урок 3).',
  obr:'Гулять: Внуки гуляют в парке. Гуляющие в парке внуки кормили уток. Гуляя в парке, внуки кормили уток.',
  body:'Вернуться, шуршать, улыбнуться, рассматривать.',
  key:'Примерные ответы. Вернуться: Тимур вернулся из похода (что сделал?). Вернувшийся из похода Тимур (какой?) показал фотографии. Вернувшись из похода, Тимур (что сделав?) показал фотографии. Шуршать: Листья шуршат под ногами (что делают?). Шуршащие листья (какие?) засыпали дорожку. Ветерок носился по саду, шурша листьями (что делая?). Улыбнуться: Алина улыбнулась нам (что сделала?). Улыбнувшаяся Алина (какая?) помахала рукой. Улыбнувшись, Алина (что сделав?) помахала рукой. Рассматривать: Мы рассматриваем карту (что делаем?). Рассматривающие карту лыжники (какие?) спорили о маршруте. Рассматривая карту, лыжники (что делая?) спорили о маршруте.<br>Проверить: глагол отвечает на вопрос «что делает? что сделал?», причастие — «какой?», деепричастие — «что делая? что сделав?».'},
 {n:11,l:1,st:3,task:'Выписать только деепричастия. Доказать, что это деепричастия: подобрать к каждому глагол-сказуемое и поставить вопрос. К каким частям речи относятся остальные слова? Почему их нельзя спутать с деепричастиями, хотя конец у них похожий?',
  obr:'Ныряя — деепричастие: плавал (что делая?) ныряя. Лесная — прилагательное: тропинка (какая?) лесная, изменяется: лесной, лесную.',
  body:'Ныряя, лесная, крича, свеча, синяя, держа, глядя, рукав, нырнув, улов, построив, архив, остановившись, гуляя, морская, умываясь, тишина, прочитав, золотая, шагая.',
  key:'Деепричастия: ныряя (плавал что делая?), крича (бежал что делая?), держа (шёл что делая?), глядя (сидел что делая?), нырнув (появился что сделав?), построив (уехал что сделав?), остановившись (оглянулся что сделав?), гуляя (встретил что делая?), умываясь (фыркал что делая?), прочитав (вернул что сделав?), шагая (пел что делая?).<br>Остальные: лесная, синяя, морская, золотая — прилагательные (какая?), изменяются по родам, числам, падежам, -ая/-яя — окончание; свеча, тишина — существительные (что?); рукав, улов, архив — существительные, -в здесь часть корня. От этих слов нельзя задать вопрос «что делая? что сделав?», и они не называют действия.'},
 {n:12,l:1,st:4,task:'Прочитать предложения. Найти главные и добавочные действия. Указать вид каждого деепричастия и объяснить, что он показывает: добавочное действие идёт одновременно с главным или закончилось раньше него. В каком предложении есть действия разного вида при одном сказуемом?',
  obr:'Убрав скотину, казачки выходили на углы улиц… → главное — выходили; убрав (сов. в.) — сначала убрали, потом выходили.',
  body:'1. Убрав скотину, казачки выходили на углы улиц и, пощёлкивая семя, усаживались на завалинках. (Л. Н. Толстой, «Казаки») 2. Оленин тоже задумался и, спустившись с крыльца, заложив руки за спину, молча стал ходить по двору. (Л. Н. Толстой, «Казаки») 3. Осмотрев обе стороны конюшни и похвалив в них чистоту, отец вышел опять на двор и приказал вывести некоторых лошадей. (С. Т. Аксаков, «Детские годы Багрова-внука») 4. Петя стиснул зубы и оглянулся, подёргивая кверху поднятой головой и размахивая рукой. (Л. Н. Толстой, «Война и мир») 5. Надышавшись на гумне ржаным ароматом новой соломы и мякины, бодро идёшь домой к ужину мимо садового вала. (И. А. Бунин, «Антоновские яблоки») 6. Потом, надев сапоги, накинув на плечи поддёвку и не застёгивая ворота рубахи, он выходит на крыльцо. (И. А. Бунин, «Антоновские яблоки»)<br>Пояснения: семя — здесь: семечки; завалинка — земляная насыпь вдоль стены избы; гумно — место для обмолота хлеба; мякина — остатки колосьев после обмолота; поддёвка — мужская верхняя одежда.',
  key:'1. Убрав (сов. в., раньше) — выходили; пощёлкивая (несов. в., одновременно) — усаживались. 2. Спустившись, заложив (сов. в., раньше) — стал ходить; слово «молча» тоже обозначает, как ходил, но это деепричастие в роли наречия (урок 3). 3. Осмотрев, похвалив (сов. в., раньше) — вышел. 4. Подёргивая, размахивая (несов. в., одновременно) — оглянулся. 5. Надышавшись (сов. в., раньше) — идёшь. 6. Надев, накинув (сов. в., раньше) и не застёгивая (несов. в., одновременно: выходит с незастёгнутым воротом) — выходит. В предложении 6 при одном сказуемом деепричастия разного вида.'},
 {n:13,l:1,st:4,task:'Мини-исследование. Доказать на примерах из предложений, что деепричастие соединяет в себе признаки глагола и наречия. Составить таблицу из двух столбиков «Признаки глагола» и «Признаки наречия»; к каждому признаку записать пример из предложений.',
  body:'1. Умываясь, Гоша громко фыркал. 2. Быстро собрав рюкзак, Рустам выбежал из дома. 3. Посадив яблоню, сторож полил её из лейки. 4. Мы долго шли по берегу, любуясь закатом. 5. Встретив учительницу, одноклассники поздоровались с ней. 6. Оглянувшись на нас, собака побежала дальше.',
  key:'Признаки глагола: 1) значение действия и вид: умываясь, любуясь (несов. в.), собрав, посадив, встретив, оглянувшись (сов. в.); 2) возвратность: умываясь, любуясь, оглянувшись (постфикс -сь); 3) переходность: собрав (что?) рюкзак, посадив (что?) яблоню, встретив (кого?) учительницу — вин. п. без предлога; 4) управление, как у глагола: любоваться (чем?) закатом — любуясь закатом; оглянуться (на кого?) на нас; 5) при деепричастии бывает наречие: быстро собрав.<br>Признаки наречия: 1) не изменяется, окончания нет: умыва-я-сь, собра-в; 2) поясняет глагол-сказуемое: фыркал (что делая?) умываясь, выбежал (что сделав?) собрав, шли (что делая?) любуясь; 3) в предложении — обстоятельство.'},
 {n:14,l:1,st:5,os:'работа с текстом',task:'Прочитать отрывок (дедушка Лодыжкин, мальчик Сергей и пудель Арто отдыхают у источника). 1) Выписать деепричастия вместе со сказуемыми, к которым они относятся. 2) Указать вид деепричастий и объяснить, одновременно ли с главным происходят добавочные действия. 3) Есть ли в отрывке причастия? Доказать, что слова «настоящие», «скромный», «прозрачная» — не причастия и не деепричастия. 4) Ответить, как деепричастия помогают автору показать неторопливый обед: заменить их сказуемыми и сравнить звучание.',
  body:'Не торопясь, медленно, в молчании, как едят настоящие труженики, принялись трое за свой скромный обед. Слышно было только, как жевали три пары челюстей. Арто ел свою долю в сторонке, растянувшись на животе и положив на хлеб обе передние лапы. <…> Насытившись, они напились воды, подставляя под струю источника жестяную кружку. Вода была прозрачная, прекрасная на вкус и такая холодная, что от неё кружка даже запотела снаружи. (А. И. Куприн, «Белый пудель»)',
  key:'1) Принялись (как?) не торопясь; ел (что сделав?) растянувшись, положив; напились (что сделав?) насытившись, (что делая?) подставляя.<br>2) Не торопясь, подставляя — несов. в., действие идёт одновременно с главным (пили, подставляя кружку). Растянувшись, положив — сов. в.: лёг и положил лапы раньше, чем начал есть, и остался в этом положении. Насытившись — сов. в., раньше главного: сначала наелись, потом напились.<br>3) Причастий в отрывке нет. Настоящие, скромный, прозрачная, холодная — прилагательные: называют постоянный признак, не образованы от глагола; запотела, жевали, принялись — глаголы-сказуемые. «Не торопясь» — деепричастие в роли наречия, рядом с наречием «медленно».<br>4) Без деепричастий: «Арто растянулся на животе, положил на хлеб лапы и ел свою долю» — действия становятся равноправными и следуют одно за другим, рассказ теряет плавность. Деепричастия делают одно действие главным, а остальные — фоном, поэтому обед кажется спокойным и неторопливым.'},
 {n:15,l:1,st:5,os:'сочинение',task:'Написать сочинение-миниатюру «Утро выходного дня» (5–7 предложений). Условия: 1) употребить не меньше пяти деепричастий, образованных от разных глаголов; 2) среди них должны быть деепричастия обоих видов; 3) деепричастие (с зависимыми словами и без них) должно стоять в начале, в середине и в конце предложения; 4) хотя бы в одном предложении при одном сказуемом — два деепричастия. Деепричастия подчеркнуть как обстоятельство, указать над ними вид. Оборот отделять запятыми, как в образцах урока (подробно — урок 3).',
  body:'Опорные слова: проснуться, потянуться, выглянуть в окошко, умываться, напевать, накрывать на стол, торопиться.',
  key:'Критерии: пять и больше деепричастий от разных глаголов; есть и несовершенный, и совершенный вид; разные позиции в предложении; в одном предложении два деепричастия при одном сказуемом; вид указан верно; действие деепричастия выполняет то же лицо, что и действие сказуемого.<br>Образец: Проснувшись (сов. в.), я долго лежал, слушая (несов. в.) воробьёв за окошком. Потом, потянувшись (сов. в.), вскочил и выглянул в окошко. Во дворе сосед, громко напевая (несов. в.), мыл машину. Нина, накрывая (несов. в.) на стол, позвала меня завтракать. Умывшись (сов. в.) и причесавшись (сов. в.), я сел за стол. Никто никуда не торопился, радуясь (несов. в.) выходному дню.'},
// ── Урок 2. Как образуются деепричастия
 {n:16,l:2,st:1,task:'Образовать от глаголов деепричастия несовершенного вида. Записать по образцу: неопределённая форма — форма «они …» — деепричастие. Выделить суффикс деепричастия и постфикс -сь.',
  obr:'Читать — они чита-ют — чита-я; учиться — они уч-атся — уч-а-сь.',
  body:'Строить, нести, слышать, играть, думать, просить, любить, смотреть, видеть, держать, учиться, возвращаться, заботиться, кричать, шуметь, спешить.',
  key:'Строить — строят — строя; нести — несут — неся; слышать — слышат — слыша; играть — играют — играя; думать — думают — думая; просить — просят — прося; любить — любят — любя; смотреть — смотрят — смотря; видеть — видят — видя; держать — держат — держа; учиться — учатся — учась; возвращаться — возвращаются — возвращаясь; заботиться — заботятся — заботясь; кричать — кричат — крича; шуметь — шумят — шумя; спешить — спешат — спеша.<br>Суффикс -я (после шипящих -а: слыша, держа, крича, спеша, учась); у возвратных глаголов после суффикса -сь.'},
 {n:17,l:2,st:1,task:'Образовать от глаголов деепричастия совершенного вида. Записать по образцу, выделить суффикс деепричастия и постфикс -сь. В каких словах вместо -в пришлось взять -вши? Почему?',
  obr:'Прочитать — прочита-ть — прочита-в; проснуться — просну-ться — просну-вши-сь.',
  body:'Построить, написать, увидеть, сказать, проснуться, вернуться, испугаться, остановиться, закрыть, умыться, рассмеяться, догадаться, заметить, связать, поздороваться, разбить.',
  key:'Построив, написав, увидев, сказав, проснувшись, вернувшись, испугавшись, остановившись, закрыв, умывшись, рассмеявшись, догадавшись, заметив, связав, поздоровавшись, разбив.<br>-вши + -сь — у возвратных глаголов (проснуться, вернуться, испугаться, остановиться, умыться, рассмеяться, догадаться, поздороваться): с -сь суффикс -в не употребляется.'},
 {n:18,l:2,st:2,task:'Распределить деепричастия по суффиксам в четыре столбика: -а/-я, -в, -вши, -ши. В столбике -а/-я подчеркнуть деепричастия совершенного вида и объяснить, от какой основы они образованы.',
  obr:'-а/-я: торопясь; найдя (сов. в.: найти — найдут — найдя).',
  body:'Кивнув, торопясь, засмеявшись, неся, выпив, слушая, оглянувшись, испёкши, найдя, держа, заметив, обжёгшись, глядя, улыбнувшись, привезя, обидев, сберёгши, ловя, перешагнув, умываясь, перейдя, догадавшись.',
  key:'-а/-я: торопясь, неся, слушая, держа, глядя, ловя, умываясь — несов. в.; найдя, привезя, перейдя — сов. в., от основы простого будущего времени (найдут, привезут, перейдут).<br>-в: кивнув, выпив, заметив, обидев, перешагнув.<br>-вши (+ -сь): засмеявшись, оглянувшись, улыбнувшись, догадавшись.<br>-ши: испёкши, обжёгшись, сберёгши — основа на согласный (испёк, обжёгся, сберёг).'},
 {n:19,l:2,st:2,task:'Образовать деепричастия несовершенного вида. 1) От глаголов на -овать, -евать: записать форму «они …» и показать, что основа у них с -у- (-ю-). 2) От глаголов с -ва- после корней да-, зна-, ста-: показать, что деепричастие образовано от основы инфинитива. Подчеркнуть деепричастия, в которых чаще всего ошибаются.',
  obr:'1) Рисовать — они рису-ют — рисуя (не «рисовая»). 2) Давать — дава-ть — давая (не «дая»).',
  body:'1) Советовать, ночевать, танцевать, путешествовать, горевать, жевать, ремонтировать, воевать. 2) Узнавать, продавать, вставать, создавать, отдавать, признавать, переставать, задавать.',
  key:'1) Советуют — советуя; ночуют — ночуя; танцуют — танцуя; путешествуют — путешествуя; горюют — горюя; жуют — жуя; ремонтируют — ремонтируя; воюют — воюя.<br>2) Узнава-ть — узнавая; продава-ть — продавая; встава-ть — вставая; создава-ть — создавая; отдава-ть — отдавая; признава-ть — признавая; перестава-ть — переставая; задава-ть — задавая.<br>Частые ошибки: «советовая», «танцевая», «узная», «встая», «отдая».'},
 {n:20,l:2,st:2,task:'Образовать деепричастия от глаголов совершенного вида на -ти, -сти, -зти и от глагола прочесть. Записать по образцу. Определить вид деепричастия и подчеркнуть слова, в которых пишут лишнюю букву й.',
  obr:'Прийти — они прид-ут — придя (что сделав? — сов. в.).',
  body:'Прийти, войти, найти, перейти, выйти, зайти, дойти, подойти, принести, отнести, привезти, увезти, привести, перевести, прочесть, произнести.',
  key:'Придя, войдя, найдя, перейдя, выйдя, зайдя, дойдя, подойдя, принеся, отнеся, привезя, увезя, приведя, переведя, прочтя (прочтут), произнеся. Все — совершенного вида (что сделав?), хотя суффикс -я.<br>Буква й: в прийти й есть только в неопределённой форме (приду, придут), поэтому придя — без й; неверно «прийдя». В войти, выйти, зайти, подойти й есть и в будущем времени (войду, выйду, зайду, подойду), поэтому он есть и в деепричастии: войдя, выйдя, зайдя, подойдя.'},
 {n:21,l:2,st:3,task:'Образовать деепричастия от глаголов каждой видовой пары. Записать в два столбика: «что делая?» и «что сделав?». Выделить суффиксы. В каких парах деепричастия образованы не по общему правилу?',
  obr:'Решать — решить: реша-я — реши-в.',
  body:'Бросать — бросить, отвечать — ответить, собирать — собрать, вставать — встать, давать — дать, узнавать — узнать, приходить — прийти, приносить — принести, умываться — умыться, возвращаться — вернуться, кричать — крикнуть, засыпать — заснуть.',
  key:'Что делая?: бросая, отвечая, собирая, вставая, давая, узнавая, приходя, принося, умываясь, возвращаясь, крича, засыпая. Что сделав?: бросив, ответив, собрав, встав, дав, узнав, придя, принеся, умывшись, вернувшись, крикнув, заснув.<br>Не по общему правилу: вставая, давая, узнавая — несов. в. от основы инфинитива (корни ста-, да-, зна- с -ва-); придя, принеся — сов. в. с суффиксом -я от основы будущего времени; умывшись, вернувшись — с -вши, потому что глагол возвратный.'},
 {n:22,l:2,st:3,task:'Распределить глаголы в два столбика: от которых деепричастие несовершенного вида образуется и от которых не образуется. Для каждого глагола второго столбика указать причину (одни согласные в основе; основа на г, к; з, с, ст, х → шипящий; исчезающий -ну-; отдельное слово). Для первого столбика записать деепричастие.',
  obr:'Резать (режут) — не образуется: з → ж. Плакать (плачут) — плача: к → ч не мешает.',
  body:'Пить, читать, беречь, плакать, мазать, рисовать, сохнуть, искать, ехать, прятать, шить, пахать, гаснуть, хохотать, стеречь, мять, петь, лезть, плясать, рвать, хотеть, тереть, ткать, кричать.',
  key:'Образуется: читать — читая; плакать — плача; рисовать — рисуя; искать — ища; прятать — пряча; хохотать — хохоча; кричать — крича.<br>Не образуется: пить (пьют), шить (шьют), мять (мнут), рвать (рвут), ткать (ткут) — в основе одни согласные; беречь (берегут), стеречь (стерегут) — основа на г; мазать (мажут), пахать (пашут), плясать (пляшут) — з, с, х сменились на шипящий; сохнуть (сох), гаснуть (гас) — -ну- исчезает в прошедшем времени; ехать, петь, лезть, хотеть — отдельные слова; тереть (трут) — одни согласные.'},
 {n:23,l:2,st:3,task:'Заменить одно из однородных сказуемых деепричастием и записать предложение. Если от глагола деепричастие несовершенного вида не образуется, заменить другое сказуемое или взять однокоренной приставочный глагол. Оборот выделить запятыми, как в образце (подробно — урок 3).',
  obr:'Вера Ивановна сидела у окошка и вязала шарф. → «Вяжа» не говорят (вязать — вяжут), поэтому заменяем другое сказуемое: Сидя у окошка, Вера Ивановна вязала шарф.',
  body:'1. Тётя пекла пироги и напевала песню. 2. Костя вернулся на дачу и сразу сел за уроки. 3. Мы ждали трамвай и разговаривали. 4. Зарина писала письмо и улыбалась. 5. Соня посмотрела в окошко и увидела радугу. 6. Карапуз плакал и тёр глаза. 7. Мальчики лезли на забор и смеялись. 8. Художник смешивал краски и что-то напевал.',
  key:'1. Напевая песню, тётя пекла пироги (печь — пекут: деепричастия нет). 2. Вернувшись на дачу, Костя сразу сел за уроки. 3. Разговаривая, мы ждали трамвай (ждать — ждут: нет; можно и: Ожидая трамвай, мы разговаривали). 4. Улыбаясь, Зарина писала письмо (писать — пишут: нет). 5. Посмотрев в окошко, Соня увидела радугу. 6. Плача, карапуз тёр глаза (плакать — плача есть; тереть — трут: нет). 7. Смеясь, мальчики лезли на забор (лезть — нет; можно: Карабкаясь на забор, мальчики смеялись). 8. Смешивая краски, художник что-то напевал.'},
 {n:24,l:2,st:3,task:'Выписать деепричастия. Записать рядом неопределённую форму глагола, от которого образовано деепричастие, указать вид и выделить суффикс.',
  obr:'Услышав — услышать, сов. в., суффикс -в.',
  body:'1. Услышав это, я почти потерял надежду. (М. Ю. Лермонтов, «Герой нашего времени») 2. Отвязав лошадь, я шагом пустился домой. (М. Ю. Лермонтов, «Герой нашего времени») 3. Прискакав в город, я отправился прямо к генералу и опрометью к нему вбежал. (А. С. Пушкин, «Капитанская дочка») 4. Осмотрев дом, Лаврецкий вышел в сад и остался им доволен. (И. С. Тургенев, «Дворянское гнездо») 5. Садясь в тарантас к Базарову, Аркадий крепко стиснул ему руку и долго ничего не говорил. (И. С. Тургенев, «Отцы и дети») 6. Погасив свечу, он накрылся ситцевым одеялом и, свернувшись под ним кренделем, заснул в ту же минуту. (Н. В. Гоголь, «Мёртвые души») 7. Придя в кухню, отец сел, дожидаясь сына, за стол. (Л. Н. Толстой, «Алёша Горшок») 8. Войдя в свой кабинет, Пьер затворил дверь и обратился к Анатолю, не глядя на него. (Л. Н. Толстой, «Война и мир»)<br>Пояснения: опрометью — очень быстро; тарантас — дорожная повозка.',
  key:'1. Услышав — услышать, сов. в., -в. 2. Отвязав — отвязать, сов. в., -в. 3. Прискакав — прискакать, сов. в., -в. 4. Осмотрев — осмотреть, сов. в., -в. 5. Садясь — садиться, несов. в., -я + -сь. 6. Погасив — погасить, сов. в., -в; свернувшись — свернуться, сов. в., -вши + -сь. 7. Придя — прийти, сов. в., -я (от основы будущего времени: придут); дожидаясь — дожидаться, несов. в., -я + -сь. 8. Войдя — войти, сов. в., -я; не глядя — глядеть, несов. в., -я.'},
 {n:25,l:2,st:3,task:'Образовать деепричастия совершенного вида и поставить в них ударение. У глаголов начать и понять сравнить ударение с прошедшим временем. Составить с четырьмя деепричастиями предложения.',
  obr:'Начать — нача́в (а в прошедшем времени: на́чал).',
  body:'Начать, понять, поднять, отдать, прибыть, закупорить, придя, найдя, войдя, принеся, переведя (у последних пяти поставить только ударение).',
  key:'Нача́в (а в прошедшем времени — на́чал), поня́в (по́нял), подня́в, отда́в, прибы́в — ударение как в неопределённой форме; закупо́рив (закупо́рить).<br>Придя́, найдя́, войдя́, принеся́, переведя́ — ударение на суффиксе -я.<br>Примерные предложения: Поня́в вопрос, Коля быстро ответил. Подня́в руку, ученица ответила на вопрос. Прибы́в на станцию, путники пересели в троллейбус. Закупо́рив банку, няня убрала её в погреб.'},
 {n:26,l:2,st:4,task:'Найти и исправить ошибки в образовании деепричастий. Объяснить каждую ошибку. Будьте внимательны: в некоторых предложениях ошибок нет.',
  body:'1. Прийдя в посёлок, Саша включил компьютер. 2. Дая советы, прабабушка улыбалась. 3. Пиша письмо, Ира задумалась. 4. Улыбаяся, школьница подала мне руку. 5. Узная новость, школьники обрадовались. 6. Требовая тишины, учитель постучал по столу. 7. Плача от обиды, сынишка убежал в комнату. 8. Встая с постели, я всегда делаю зарядку. 9. Ища ключи, Катя перевернула всю сумку. 10. Пья чай, Иван Петрович читал газету.',
  key:'1. Придя — без й (придут). 2. Давая — корень да- с -ва-: от основы инфинитива. 3. Ошибка: от «писать» (пишут) деепричастия несовершенного вида нет; можно: Сочиняя письмо… или Когда Ира писала письмо, она задумалась. 4. Улыбаясь — у деепричастий -сь, а не -ся. 5. Узнав новость (или: узнавая) — «узная» неверно. 6. Требуя — основа «они требуют». 7. Ошибки нет: плакать — плачут — плача. 8. Вставая — корень ста- с -ва-. 9. Ошибки нет: искать — ищут — ища. 10. Ошибка: от «пить» (пьют) деепричастия нет; можно: Попивая чай, Иван Петрович читал газету.'},
 {n:27,l:2,st:4,task:'Заменить выделенный глагол деепричастием. Если от него деепричастие не образуется, подобрать однокоренной приставочный или близкий по смыслу глагол либо перестроить предложение. Записать предложения. Запятые поставить так, как в образце: оборот отделяется запятыми (подробно — урок 3).',
  body:'1. Мы (ехали) по степи и любовались закатом. 2. Илья (лез) на дерево и громко кричал. 3. Ученица (пела) и кружилась по комнате. 4. Шестиклассники (ждали) поезда и смотрели в окошко. 5. Анна Петровна (пекла) блины и рассказывала сказку. 6. Егор (резал) хлеб и смеялся. 7. Мы (рвали) ромашки и плели венки. 8. Рыжик (рвал) бумагу и мурлыкал. 9. Бельё (сохло) на верёвке и хлопало на ветру.',
  key:'1. Проезжая по степи, мы любовались закатом. 2. Карабкаясь на дерево, Илья громко кричал. 3. Напевая, ученица кружилась по комнате. 4. Ожидая поезда (поджидая поезд), шестиклассники смотрели в окошко. 5. Анна Петровна пекла блины, рассказывая сказку (от «печь» деепричастия нет — заменено другое сказуемое). 6. Нарезая хлеб, Егор смеялся. 7. Срывая ромашки, мы плели венки (рвать — рвут: нет). 8. Разрывая бумагу, Рыжик мурлыкал. 9. Бельё сохло на верёвке, хлопая на ветру (от «сохнуть» деепричастия нет; можно: Высыхая на верёвке, бельё хлопало на ветру).'},
 {n:28,l:2,st:4,task:'Выписать деепричастия с суффиксом -а/-я и распределить их в два столбика: несовершенного вида и совершенного вида. Для деепричастий совершенного вида записать форму будущего времени «они …», от основы которой они образованы.',
  body:'1. Подойдя к карете, я увидел, что всё было устроено. (С. Т. Аксаков, «Детские годы Багрова-внука») 2. Андрюша, краснея и улыбаясь, поднёс гостю свою тетрадку. (И. С. Тургенев, «Записки охотника») 3. Уходя, она обернулась, чтобы в последний раз улыбнуться и кивнуть Аркадию. (И. С. Тургенев, «Отцы и дети») 4. Войдя в свой кабинет, Пьер затворил дверь и обратился к Анатолю, не глядя на него. (Л. Н. Толстой, «Война и мир») 5. Кузнец, не видя ничего, растянулся и сам со всем усердием на полу. (Н. В. Гоголь, «Ночь перед Рождеством») 6. Ростов, не заходя домой, взял лошадь и поехал в штаб. (Л. Н. Толстой, «Война и мир») 7. Ксюша, прочтя записку, рассмеялась. 8. Переведя дыхание, бегун снова прибавил скорость.',
  key:'Несов. в.: краснея, улыбаясь, уходя, не глядя, не видя, не заходя.<br>Сов. в.: подойдя (подойдут), войдя (войдут), прочтя (прочтут), переведя (переведут).<br>Суффикс -а/-я сам по себе не указывает на вид: вид определяется по вопросу (что сделав?) и по глаголу.'},
 {n:29,l:2,st:5,task:'Тонкость. У писателей XIX века встречаются формы деепричастий, которые сейчас звучат устаревшими. Выписать такие деепричастия, записать рядом современную форму и объяснить, чем они отличаются. Какие деепричастия в отрывках образованы по современным правилам?',
  body:'1. Но вот, насытясь разрушеньем / И наглым буйством утомясь, / Нева обратно повлеклась, / Своим любуясь возмущеньем / И покидая с небреженьем / Свою добычу. (А. С. Пушкин, «Медный всадник») 2. Пугачёв на первом месте сидел, облокотясь на стол и подпирая чёрную бороду своим широким кулаком. (А. С. Пушкин, «Капитанская дочка») 3. Наконец мать, помолясь, погасила свечки и легла на свою постель. (С. Т. Аксаков, «Детские годы Багрова-внука») 4. Увидав мать, она вскочила и бросилась к ней. (Л. Н. Толстой, «Война и мир») 5. Наконец кучер, потерявши терпение, прогнал и дядю Митяя и дядю Миняя, и хорошо сделал… (Н. В. Гоголь, «Мёртвые души») 6. Мы разбудили его, и он, благословясь, принялся за чтение. (С. Т. Аксаков, «Детские годы Багрова-внука»)<br>Пояснения: небреженье — пренебрежение; благословиться — попросить благословения перед делом.',
  key:'Устаревшие формы: насытясь — насытившись; утомясь — утомившись; облокотясь — облокотившись; помолясь — помолившись; благословясь — благословившись (у глаголов совершенного вида на -ить(ся) раньше употреблялись формы на -я(сь), сейчас — на -в, -вшись); увидав — увидев (старый вариант от «увидать»); потерявши — потеряв (-вши без -сь сейчас разговорное или устаревшее).<br>По современным правилам: любуясь, покидая, подпирая — несов. в., от основы настоящего времени (любуются, покидают, подпирают).'},
 {n:30,l:2,st:5,os:'сочинение',task:'Написать инструкцию «Как приготовить чай для гостей» (6–7 предложений). Условия: 1) употребить не меньше шести деепричастий от разных глаголов; 2) среди них — деепричастие на -я совершенного вида (от глагола на -ти), возвратное деепричастие на -вшись и деепричастие от глагола на -овать или -евать; 3) не употреблять деепричастий несовершенного вида от глаголов лить, ждать, печь (подобрать замену). Над каждым деепричастием указать вид и выделить суффикс. Запятые поставить так, как в образце: оборот отделяется запятыми (подробно — урок 3).',
  body:'Опорные слова: прийти на кухню, налить воду, вскипятить, ополоснуть чайник, насыпать заварку, подождать, советовать, расставить чашки, угощать.',
  key:'Критерии: шесть и больше деепричастий от разных глаголов; есть деепричастие на -я совершенного вида (придя, принеся), возвратное на -вшись, деепричастие от глагола на -овать/-евать (советуя, пробуя); нет форм «лья», «жда», «пека»; вид и суффиксы указаны верно.<br>Образец: Придя (сов. в., -я) на кухню, сначала вымойте руки. Налив (сов. в., -в) в чайник свежей воды, поставьте его на огонь. Вскипятив (сов. в., -в) воду, ополосните заварочный чайник кипятком. Насыпав (сов. в., -в) заварку, залейте её и накройте чайник салфеткой. Подождав (сов. в., -в) пять минут, разлейте чай по чашкам. Угощая (несов. в., -я) гостей, предложите им мёд и варенье, советуя (несов. в., -я) попробовать каждое. Убедившись (сов. в., -вши-сь), что всем хватило чая, можно садиться и самим.'},
// ── Урок 3. Деепричастный оборот. Запятые
 {n:31,l:3,st:1,task:'Переписать предложения, выделяя деепричастный оборот запятыми. Подчеркнуть оборот как одно обстоятельство (точка — тире).',
  obr:'Поднявшись на холм мы увидели всё село. → Поднявшись на холм, мы увидели всё село.',
  body:'1. Закончив работу мастер убрал инструменты. 2. Мы долго стояли на мосту глядя на ледоход. 3. Услышав звонок ученики вышли в коридор. 4. Скворец сидел на ветке распевая свою песню. 5. Перепрыгнув через лужу Аня побежала дальше. 6. Няня шила платье для куклы тихо напевая. 7. Сделав несколько шагов Тимоша упал на ковёр. 8. Лиса кралась по опушке прислушиваясь к каждому шороху. 9. Перелистав учебник Алёша нашёл нужное правило. 10. Пароход медленно отходил от пристани протяжно гудя.',
  key:'1. Закончив работу, мастер… 2. …на мосту, глядя на ледоход. 3. Услышав звонок, ученики… 4. …на ветке, распевая свою песню. 5. Перепрыгнув через лужу, Аня… 6. …для куклы, тихо напевая. 7. Сделав несколько шагов, Тимоша… 8. …по опушке, прислушиваясь к каждому шороху. 9. Перелистав учебник, Алёша… 10. …от пристани, протяжно гудя.<br>Оборот в начале — запятая после него, в конце — перед ним.'},
 {n:32,l:3,st:2,task:'Расставить запятые. Найти оборот, стоящий в середине предложения, и объяснить, почему в этом случае ставятся две запятые. В каких предложениях оборот стоит после подлежащего-местоимения?',
  obr:'Мы поднявшись на холм увидели село. → Мы, поднявшись на холм, увидели село: оборот в середине выделяется с двух сторон.',
  body:'1. Котик наигравшись с клубком уснул прямо на полу. 2. Я раскрыв зонт пошёл к остановке. 3. Одноклассники взявшись за руки водили хоровод вокруг ёлки. 4. Она оглянувшись на нас помахала рукой. 5. Солнышко пробившись сквозь тучи осветило поле. 6. Мы спустившись к речке развели небольшой костёр. 7. Вратарь прыгнув в угол отбил мяч. 8. Он вспомнив о поручении вернулся в класс. 9. Ласточки летая низко над землёй ловили мошек. 10. Школьница слушала сказку затаив дыхание.',
  key:'1. Котик, наигравшись с клубком, уснул… 2. Я, раскрыв зонт, пошёл… 3. Одноклассники, взявшись за руки, водили… 4. Она, оглянувшись на нас, помахала… 5. Солнышко, пробившись сквозь тучи, осветило… 6. Мы, спустившись к речке, развели… 7. Вратарь, прыгнув в угол, отбил… 8. Он, вспомнив о поручении, вернулся… 9. Ласточки, летая низко над землёй, ловили… 10. Без запятых: «затаив дыхание» — устойчивое выражение (= очень внимательно).<br>Оборот в середине отделяется и от подлежащего, и от сказуемого — две запятые. После местоимения — в предложениях 2, 4, 6, 8; правило то же, что и после существительного (в отличие от причастного оборота, место для деепричастного оборота не важно).'},
 {n:33,l:3,st:2,task:'Расставить запятые при одиночных деепричастиях и при однородных деепричастиях. Объяснить, почему одиночное деепричастие здесь выделяется: какое второе действие оно называет?',
  obr:'Подумав Уля согласилась. → Подумав, Уля согласилась: сначала подумала, потом согласилась.',
  body:'1. Устав школьники присели отдохнуть. 2. Девчонки смеясь выбежали во двор. 3. Испугавшись воробьи вспорхнули с ветки. 4. Водопад шумел клокоча и пенясь. 5. Проснувшись Андрюша позвал Галю. 6. Полкан повизгивая и подпрыгивая бежал за хозяином. 7. Отдохнув мы снова взялись за вёсла. 8. Опомнившись Олег бросился догонять друзей. 9. Ветерок гнал облака свистя и завывая. 10. Нахмурившись рыбак отложил газету.',
  key:'1. Устав, школьники… (причина: присели, потому что устали). 2. Девчонки, смеясь, выбежали… (действие рядом с главным: выбежали и смеялись). 3. Испугавшись, воробьи… (причина). 4. Водопад шумел, клокоча и пенясь (два однородных деепричастия с «и» — запятой между ними нет, выделяются вместе). 5. Проснувшись, Андрюша… (время: когда проснулся). 6. Полкан, повизгивая и подпрыгивая, бежал… 7. Отдохнув, мы… 8. Опомнившись, Олег… 9. …облака, свистя и завывая. 10. Нахмурившись, рыбак…'},
 {n:34,l:3,st:2,task:'Расставить запятые при однородных деепричастных оборотах. Подчеркнуть союз «и» между оборотами. Объяснить, когда между оборотами ставится запятая.',
  obr:'Оглянувшись помахав нам рукой Даша скрылась за углом. → Оглянувшись, помахав нам рукой, Даша скрылась за углом (без союза — запятая между оборотами).',
  body:'1. Барсик сидел на подоконнике жмурясь и греясь на солнце. 2. Собрав рюкзак проверив палатку путешественники легли спать. 3. Мадина ходила по кухне что-то напевая и переставляя кастрюли. 4. Добежав до ворот и оглянувшись школьник остановился. 5. Река текла среди холмов извиваясь блестя на солнце. 6. Выйдя на крыльцо и вдохнув свежий воздух пасечник улыбнулся. 7. Пёс носился по двору лая на кур и пугая гусей. 8. Повесив куртку переобувшись Рустам прошёл в комнату.',
  key:'1. …на подоконнике, жмурясь и греясь на солнце. 2. Собрав рюкзак, проверив палатку, путешественники… 3. …по кухне, что-то напевая и переставляя кастрюли. 4. Добежав до ворот и оглянувшись, школьник… 5. …среди холмов, извиваясь, блестя на солнце. 6. Выйдя на крыльцо и вдохнув свежий воздух, пасечник… 7. …по двору, лая на кур и пугая гусей. 8. Повесив куртку, переобувшись, Рустам…<br>С одиночным союзом «и» запятой между оборотами нет, вся группа выделяется как одно целое; без союза между оборотами ставится запятая.'},
 {n:35,l:3,st:3,task:'Расставить запятые. Определить, что соединяет союз «и»: два деепричастия (оборота) или два сказуемых. Объяснить, почему в одних предложениях запятая стоит после «и», а в других — нет.',
  obr:'Федя встал и подойдя к окошку открыл форточку. → Федя встал и, подойдя к окошку, открыл форточку: «и» соединяет сказуемые встал и открыл, оборот относится ко второму.',
  body:'1. Ксюша села за столик и раскрыв тетрадь принялась за упражнение. 2. Улыбаясь и кивая нам прабабушка вышла на крыльцо. 3. Шарик подбежал к миске и понюхав её отвернулся. 4. Ученик подумав и посоветовавшись с приятелем выбрал тему доклада. 5. Ветерок подхватил листья и закружив их унёс за реку. 6. Мы вышли из леса и перейдя ручеёк оказались на поляне. 7. Юля слушала музыку закрыв глаза и покачиваясь в такт. 8. Он взял повесть и полистав её поставил обратно на полку.',
  key:'1. …за столик и, раскрыв тетрадь, принялась… («и» — между сказуемыми). 2. Улыбаясь и кивая нам, прабабушка… («и» — между деепричастиями, запятой после «и» нет). 3. …к миске и, понюхав её, отвернулся. 4. Ученик, подумав и посоветовавшись с приятелем, выбрал… (между деепричастиями). 5. …листья и, закружив их, унёс… 6. …из леса и, перейдя ручеёк, оказались… 7. …музыку, закрыв глаза и покачиваясь в такт (между деепричастиями). 8. …повесть и, полистав её, поставил…<br>Проверка: убрать оборот. Если остаются два сказуемых с «и» (села и принялась), союз за пределами оборота — запятая после «и». Если «и» исчезает вместе с оборотом, оно соединяет деепричастия — запятой нет.'},
 {n:36,l:3,st:3,task:'Переписать предложения, расставляя пропущенные запятые. Подчеркнуть деепричастия и обороты как обстоятельства. В каких предложениях оборот стоит после союза «и»?',
  obr:'Брат встал и подойдя к окну открыл форточку. → Брат встал и, подойдя к окну, открыл форточку.',
  body:'1. Лаврецкий посмотрел ей вслед и понурив голову отправился назад по улице. (И. С. Тургенев, «Дворянское гнездо») 2. Фенечка принесла чашку чаю и поставив её на столик хотела было удалиться. (И. С. Тургенев, «Отцы и дети») 3. Старик сел против него на свои голые пятки и закрыв глаза поднял руки ладонями кверху. (Л. Н. Толстой, «Хаджи-Мурат») 4. Она бросилась ей навстречу и обняв её заплакала на её плече. (Л. Н. Толстой, «Война и мир») 5. Маленькая княгиня взяв платье из рук горничной подходила к княжне Марье. (Л. Н. Толстой, «Война и мир») 6. Княжна Марья опустив голову вышла из круга и пошла в дом. (Л. Н. Толстой, «Война и мир») 7. Расчистив дорогу Денисов остановился у входа на мост. (Л. Н. Толстой, «Война и мир») 8. Недопюскин вошёл приятно раскланиваясь и улыбаясь. (И. С. Тургенев, «Записки охотника») 9. Гости встали и уехали обещаясь приехать к обеду. (Л. Н. Толстой, «Война и мир») 10. Погасив свечу он накрылся ситцевым одеялом и свернувшись под ним кренделем заснул в ту же минуту. (Н. В. Гоголь, «Мёртвые души»)<br>Пояснения: обещаться — здесь: обещать.',
  key:'1. …вслед и, понурив голову, отправился… 2. …чаю и, поставив её на столик, хотела… 3. …пятки и, закрыв глаза, поднял… 4. …навстречу и, обняв её, заплакала… 5. Маленькая княгиня, взяв платье из рук горничной, подходила… 6. Княжна Марья, опустив голову, вышла… 7. Расчистив дорогу, Денисов… 8. Недопюскин вошёл, приятно раскланиваясь и улыбаясь (однородные деепричастия с «и» — без запятой между ними). 9. …и уехали, обещаясь приехать к обеду. 10. Погасив свечу, он накрылся ситцевым одеялом и, свернувшись под ним кренделем, заснул…<br>После союза «и» оборот (или деепричастие) стоит в предложениях 1, 2, 3, 4, 10: «и» соединяет два сказуемых.'},
 {n:37,l:3,st:3,task:'Расставить запятые там, где они нужны. Объяснить, почему в одних предложениях слова молча, лёжа, стоя, сидя, шутя, не спеша выделяются, а в других — нет. Заменить наречием те из них, которые запятыми не выделяются.',
  obr:'Мы шли молча. (без запятых: шли как? молча = безмолвно) — Молча кивнув нам старик ушёл. → Молча кивнув нам, старик ушёл (молча — при деепричастии кивнув, это оборот).',
  body:'1. Мальчишки слушали учителя молча. 2. Молча собрав вещи Стёпа вышел из дома. 3. Дед любит читать лёжа. 4. Лёжа на тёплом песке мы смотрели на облака. 5. Зрители аплодировали стоя. 6. Стоя на табуретке Гоша дотянулся до полки. 7. Сидя у костра путники пели песни. 8. Кошка спала сидя. 9. Сильный спортсмен поднял штангу шутя. 10. Шутя и смеясь девочки шли из школы. 11. Мы шли к речке не спеша. 12. Не спеша поднявшись на крыльцо соседка постучала в ворота.',
  key:'Без запятых (деепричастие в роли наречия, образ действия, стоит при сказуемом): 1 (слушали безмолвно), 3 (читать в лежачем положении), 5, 8, 9 (поднял легко), 11 (шли медленно).<br>С запятыми: 2. Молча собрав вещи, Стёпа… (молча — при деепричастии собрав: оборот). 4. Лёжа на тёплом песке, мы… (есть зависимые слова). 6. Стоя на табуретке, Гоша… 7. Сидя у костра, путники… 10. Шутя и смеясь, девочки… (однородные деепричастия перед сказуемым — добавочные действия). 12. Не спеша поднявшись на крыльцо, соседка… («не спеша» относится к деепричастию поднявшись, весь оборот выделяется).'},
 {n:38,l:3,st:3,task:'Расставить запятые. Найти устойчивые выражения (фразеологизмы) и записать рядом их значение одним словом или сочетанием. В каких предложениях те же слова употреблены в прямом значении?',
  obr:'Волонтёры трудились засучив рукава (= усердно, без запятых). Засучив рукава рубашки Нина стала мыть посуду. → Засучив рукава рубашки, Нина… (прямое значение — оборот).',
  body:'1. Мальчишки бежали к речке сломя голову. 2. Одноклассники слушали рассказ о путешествии затаив дыхание. 3. Затаив дыхание пловец нырнул в глубину. 4. Хватит сидеть сложа руки. 5. Мастер работал не покладая рук. 6. Засучив рукава свитера Боря принялся лепить снеговика. 7. Сынишка стоял перед витриной разинув рот. 8. Разинув клюв птенец ждал маму. 9. Мы бежали на электричку высунув язык. 10. Высунув язык пёс лежал в тени.',
  key:'Фразеологизмы, без запятых: 1 (сломя голову = очень быстро), 2 (затаив дыхание = очень внимательно), 4 (сложа руки = бездельничая), 5 (не покладая рук = не отдыхая), 7 (разинув рот = с удивлением), 9 (высунув язык = изо всех сил).<br>Прямое значение, с запятыми: 3. Затаив дыхание, пловец нырнул… 6. Засучив рукава свитера, Боря… 8. Разинув клюв, птенец… 10. Высунув язык, пёс лежал в тени.'},
 {n:39,l:3,st:3,task:'Составить предложения по схемам. Обозначения: [Д] — деепричастный оборот, Д — одиночное деепричастие, = — сказуемое. Поставить запятые, как показано в схеме.',
  obr:'[Д], —=. → Услышав шаги, собака залаяла.',
  body:'1) [Д], —=. 2) —=, [Д]. 3) —, [Д], =. 4) Д, —=. 5) [Д и Д], —=. 6) —= и, [Д], =. 7) [Д], [Д], —=. 8) —= молча.',
  key:'Примерные ответы. 1) Открыв окошко, Катя впустила свежий воздух. 2) Мы сидели на берегу, слушая шум волн. 3) Света, прочитав письмо, улыбнулась. 4) Подумав, Коля согласился. 5) Встав пораньше и умывшись, Костя сделал зарядку. 6) Учитель кивнул и, подойдя к доске, написал тему урока. 7) Сняв куртку, повесив её на крючок, Аня прошла в комнату. 8) Мальчишки слушали молча.<br>Проверить: запятые стоят там, где они показаны в схеме; в схеме 5 между деепричастиями с «и» запятой нет; в схеме 6 запятая после «и»; в схеме 8 — слово-наречие без запятых.'},
 {n:40,l:3,st:2,task:'Записать каждое предложение три раза, переставляя деепричастный оборот: в начало предложения, в середину (после подлежащего) и в конец. Расставить запятые. Изменяется ли правило?',
  obr:'Спасаясь от ливня, альпинисты забежали под навес. Альпинисты, спасаясь от ливня, забежали под навес. Альпинисты забежали под навес, спасаясь от ливня.',
  body:'1. Догнав мяч, Серёжа ударил по воротам. 2. Ёж, свернувшись клубком, лежал под кустом. 3. Зарина разбирала старые фотографии, вспоминая детство. 4. Заметив нас, белка юркнула на ветку. 5. Повар, попробовав суп, добавил соли.',
  key:'1. Догнав мяч, Серёжа ударил по воротам. Серёжа, догнав мяч, ударил по воротам. Серёжа ударил по воротам, догнав мяч. 2. Свернувшись клубком, ёж лежал под кустом. Ёж, свернувшись клубком, лежал под кустом. Ёж лежал под кустом, свернувшись клубком. 3. Вспоминая детство, Зарина разбирала старые фотографии. Зарина, вспоминая детство, разбирала… Зарина разбирала старые фотографии, вспоминая детство. 4. Заметив нас, белка юркнула на ветку. Белка, заметив нас, юркнула на ветку. Белка юркнула на ветку, заметив нас. 5. Попробовав суп, повар добавил соли. Повар, попробовав суп, добавил соли. Повар добавил соли, попробовав суп.<br>Правило не изменяется: деепричастный оборот выделяется всегда, где бы он ни стоял. Меняется только количество запятых: в начале и в конце — одна, в середине — две.'},
 {n:41,l:3,st:4,task:'Пунктуационный разбор. Объяснить каждую запятую в предложениях: деепричастный оборот, одиночное деепричастие, однородные члены, причастный оборот. Над запятыми при деепричастиях поставить «Д», при однородных членах — «О», при причастном обороте — «П».',
  body:'1. И ветер бушевал среди ненастья, качая верхушки деревьев, стуча ставнями и напевая мне в моей постели о десятках людей, лишённых тепла и приюта. (В. Г. Короленко, «Дети подземелья») 2. Отворив дверь в залу, Пьер увидал Наташу, сидевшую у окна с худым, бледным и злым лицом. (Л. Н. Толстой, «Война и мир») 3. Между тем Тыбурций быстро отпер входную дверь и, остановившись на пороге, в одну секунду оглядел нас обоих своими острыми, рысьими глазами. (В. Г. Короленко, «Дети подземелья») 4. Холодно поздоровавшись и пригласив сесть Чернышёва, Николай уставился на него своими безжизненными глазами. (Л. Н. Толстой, «Хаджи-Мурат») 5. Пожав руку моему новому знакомому, я протянул её также и девочке. (В. Г. Короленко, «Дети подземелья»)<br>Пояснения: рысий — как у рыси.',
  key:'1. Ненастья, (Д) — начало ряда однородных деепричастных оборотов; деревьев, (Д, О) — между однородными оборотами без союза; перед «и» запятой нет (однородные с одиночным «и»); людей, (П) — причастный оборот «лишённых тепла и приюта» после определяемого слова. 2. Залу, (Д) — оборот в начале; Наташу, (П) — причастный оборот после определяемого слова; худым, (О) — однородные определения, перед «и» запятой нет. 3. И, (Д) пороге, (Д) — оборот после союза «и», который соединяет сказуемые «отпер» и «оглядел»; острыми, (О) — однородные определения. 4. Чернышёва, (Д) — два однородных оборота с «и» выделяются вместе, запятая после всей группы. 5. Знакомому, (Д) — оборот в начале.'},
 {n:42,l:3,st:4,task:'Расставить запятые. Разграничить деепричастный и причастный обороты: над деепричастным оборотом написать «Д», над причастным — «П». Объяснить, почему причастный оборот выделяется не всегда, а деепричастный — всегда.',
  obr:'Собранные в роще грибы мы разложили на газете (П, перед словом — без запятых). Собрав грибы мы разложили их на газете. → Собрав грибы, мы… (Д — всегда).',
  body:'1. Покрытые инеем деревья стояли неподвижно. 2. Покрыв стол скатертью Галя поставила вазу с цветами. 3. Дорога ведущая к озеру заросла травой. 4. Ведя велосипед за руль Миша поднимался в гору. 5. Школьники построившие скворечник повесили его на берёзу. 6. Построив скворечник школьники повесили его на берёзу. 7. Наташа сидевшая у окошка обернулась. 8. Сидя у окошка Наташа читала. 9. Мы шли по тропинке протоптанной грибниками. 10. Мы шли по тропинке разглядывая следы на снегу.',
  key:'1. П перед определяемым словом — без запятых. 2. Д: Покрыв стол скатертью, Галя… 3. П после слова: Дорога, ведущая к озеру, заросла… 4. Д: Ведя велосипед за руль, Миша… 5. П после слова: Школьники, построившие скворечник, повесили… 6. Д: Построив скворечник, школьники… 7. П после слова: Наташа, сидевшая у окошка, обернулась. 8. Д: Сидя у окошка, Наташа читала. 9. П после слова: …по тропинке, протоптанной грибниками. 10. Д: …по тропинке, разглядывая следы на снегу.<br>Причастный оборот выделяется, только если стоит после определяемого слова (или относится к личному местоимению); деепричастный оборот выделяется в любом месте предложения.'},
 {n:43,l:3,st:4,task:'Найти и исправить пунктуационные ошибки. Объяснить каждое исправление. Есть предложения без ошибок.',
  body:'1. Одноклассники, слушали учителя, молча. 2. Набрав воды в ведро Вера Ивановна полила грядки. 3. Мурзик играл с клубком, подпрыгивая, и кувыркаясь. 4. Денис вскочил, и схватив портфель, побежал в школу. 5. Мы трудились не покладая рук. 6. Благодаря, помощи друзей, мы быстро переехали. 7. Белка, распушив хвост, перепрыгнула на соседнюю сосну. 8. Вова читал, лёжа. 9. Оглянувшись, и никого не увидев школьница пошла дальше. 10. Спортсмены, бежали, сломя голову.',
  key:'1. Одноклассники слушали учителя молча — «молча» в роли наречия, запятые не нужны. 2. Набрав воды в ведро, Вера Ивановна… — пропущена запятая после оборота. 3. …с клубком, подпрыгивая и кувыркаясь — перед «и» между однородными деепричастиями запятая не нужна. 4. Денис вскочил и, схватив портфель, побежал… — «и» соединяет сказуемые, запятая после «и». 5. Ошибок нет. 6. Благодаря помощи друзей мы быстро переехали — «благодаря» предлог, правило о деепричастиях к нему не относится. 7. Ошибок нет. 8. Вова читал лёжа — деепричастие в роли наречия. 9. Оглянувшись и никого не увидев, школьница… — однородные с «и» без запятой между ними, запятая после всей группы. 10. Спортсмены бежали сломя голову — фразеологизм, запятые не нужны; между подлежащим и сказуемым запятой нет.'},
 {n:44,l:3,st:4,task:'Задание в формате ОГЭ. Расставить знаки препинания. Указать цифры, на месте которых в предложении должны стоять запятые.',
  body:'1. Ветерок (1) подхватив сухие листья (2) закружил их над дорогой (3) и (4) поднявшись выше (5) унёс за реку. 2. Мальчики шли гуськом (1) и (2) изредка оглядываясь на отставших (3) перекликались (4) с ними. 3. Няня (1) сложив руки на коленях (2) слушала нас (3) затаив дыхание. 4. Рыбаки (1) не покладая рук (2) чинили сети (3) переговариваясь и (4) посмеиваясь. 5. Подойдя к речке (1) мы (2) сняв обувь (3) осторожно вошли в холодную воду (4) и (5) поёживаясь (6) побрели к другому берегу.',
  key:'1. 1, 2, 4, 5 (оборот после подлежащего; второй оборот после «и», соединяющего сказуемые). 2. 2, 3 (оборот после «и», соединяющего сказуемые). 3. 1, 2 («сложив руки на коленях» — прямое значение, оборот; «затаив дыхание» — фразеологизм). 4. 3 («не покладая рук» — фразеологизм; однородные деепричастия с «и» выделяются вместе). 5. 1, 2, 3, 5, 6.'},
 {n:45,l:3,st:5,os:'диктант',task:'Диктант с грамматическим заданием. 1) Записать текст под диктовку (или переписать, расставляя запятые). 2) Подчеркнуть деепричастия и деепричастные обороты как обстоятельства. 3) Объяснить, почему не выделены слова «не спеша», «молча» и выражение «затаив дыхание».',
  body:'Утро на речке. Проснувшись на рассвете мы с лесником отправились на реку. Мы не спеша шли по тропинке вдыхая прохладный воздух и прислушиваясь к птичьим голосам. Туман поднимаясь над водой медленно таял в первых лучах солнышка. Дойдя до старой ивы лесник остановился и оглядев берег выбрал удобное место. Мы размотали удочки и насадив червей забросили их подальше от берега. Поплавки покачиваясь на волнах долго не шевелились. Я сидел молча и следил за своим поплавком затаив дыхание. Вдруг поплавок дрогнул и нырнув исчез под водой. Подсекая рыбу я чуть не упал в реку. Лесник улыбаясь помог мне вытащить окуня. Вернувшись в деревню к обеду мы с гордостью показали Мадине улов.',
  key:'Проснувшись на рассвете, мы с лесником отправились на реку. Мы не спеша шли по тропинке, вдыхая прохладный воздух и прислушиваясь к птичьим голосам. Туман, поднимаясь над водой, медленно таял в первых лучах солнышка. Дойдя до старой ивы, лесник остановился и, оглядев берег, выбрал удобное место. Мы размотали удочки и, насадив червей, забросили их подальше от берега. Поплавки, покачиваясь на волнах, долго не шевелились. Я сидел молча и следил за своим поплавком затаив дыхание. Вдруг поплавок дрогнул и, нырнув, исчез под водой. Подсекая рыбу, я чуть не упал в реку. Лесник, улыбаясь, помог мне вытащить окуня. Вернувшись в деревню к обеду, мы с гордостью показали Мадине улов.<br>«Не спеша», «молча» — деепричастия в роли наречия (шли медленно, сидел безмолвно), они стоят прямо при сказуемом; «затаив дыхание» — фразеологизм (= очень внимательно).'},
 {n:46,l:3,st:5,task:'Тонкость. Сравнить, как писатели расставили знаки при одиночных деепричастиях и сочетаниях с ними. Объяснить, в каких случаях деепричастие после сказуемого выделено (называет второе действие или имеет зависимые слова), а в каких нет (обозначает только образ действия и близко к наречию). Почему в предложении 6 сочетание «не торопясь» выделено, хотя «не спеша» в учебнике даётся без запятых?',
  body:'1. Лукашка понимал её и всё кивал, слегка улыбаясь. (Л. Н. Толстой, «Казаки») 2. Мария Кириловна плакала молча. (А. С. Пушкин, «Дубровский») 3. Минут пять спустя они открыли глаза и переглянулись молча. (И. С. Тургенев, «Отцы и дети») 4. В течение всей дороги Касьян сохранял упорное молчание и на мои вопросы отвечал отрывисто и нехотя. (И. С. Тургенев, «Записки охотника») 5. Села рядом со мною и замолчала, покачиваясь. (М. Горький, «Детство») 6. Павел Петрович начал, не торопясь, намазывать масло на хлеб. (И. С. Тургенев, «Отцы и дети») 7. Глубоко оскорблённая, она села под окошко и до глубокой ночи сидела не раздеваясь… (А. С. Пушкин, «Дубровский»)',
  key:'1. «Слегка улыбаясь» — оборот (есть зависимое слово), выделяется. 2, 3. «Молча» — образ действия при сказуемом, деепричастие в роли наречия — без запятых. 4. «Нехотя» — наречие (= неохотно), однородно с наречием «отрывисто», без запятых. 5. «Покачиваясь» — второе действие: замолчала и при этом покачивалась; автор выделяет его, подчёркивая добавочное действие. 7. «Не раздеваясь» — образ действия (сидела как? одетая), без запятых.<br>6. «Не торопясь» стоит не после сказуемого, а в середине, между частями сказуемого «начал намазывать», и автор выделяет его как добавочное действие. Решение для одиночного деепричастия часто зависит от его места и смысла, поэтому в обычных заданиях даются только ясные случаи (урок 3, «Тонкости»).'},
// ── Урок 4. Правописание деепричастий
 {n:47,l:4,st:1,task:'Раскрыть скобки. Записать деепричастия с не раздельно. Подчеркнуть не и деепричастие и над деепричастием поставить вопрос.',
  obr:'Ушёл, (не)попрощавшись. → Ушёл (что сделав?) не попрощавшись.',
  body:'1. Мы шли по бору, (не)зная дороги. 2. (Не)дождавшись троллейбуса, мальчишки пошли пешком. 3. (Не)раздеваясь, карапуз уснул на диване. 4. Кот сидел у норки, (не)сводя с неё глаз. 5. (Не)найдя ключа, тётя позвонила соседке. 6. Илья ответил урок, (не)запинаясь ни разу. 7. (Не)успев позавтракать, я побежал в школу. 8. Тамара переписала упражнение, (не)сделав ни одной ошибки. 9. Ученица слушала, (не)перебивая рассказчика. 10. (Не)умея плавать, Геня не заходил глубоко.',
  key:'1. Не зная. 2. Не дождавшись. 3. Не раздеваясь. 4. Не сводя. 5. Не найдя. 6. Не запинаясь. 7. Не успев. 8. Не сделав. 9. Не перебивая. 10. Не умея.<br>Не с деепричастиями пишется раздельно — так же, как с глаголами (не знать — не зная), независимо от того, есть зависимые слова или нет.'},
 {n:48,l:4,st:2,task:'Раскрыть скобки. Распределить деепричастия в два столбика: с не слитно и с не раздельно. Для каждого слова со слитным написанием доказать, что без не оно не употребляется.',
  obr:'(Не)навидя ложь — ненавидя: «навидя» не говорят; (не)любя манную кашу — не любя: «любя» употребляется.',
  body:'1. (Не)годуя, зрители свистели. 2. (Не)навидя скуку, Гриша всегда находил себе дело. 3. Мы ждали, (не)отрывая глаз от дороги. 4. (Не)доумевая, гости переглядывались. 5. (Не)взлюбив нового соседа, пёс лаял на него каждый день. 6. Он ушёл, (не)дослушав нас. 7. (Не)истовствуя, болельщики требовали гола. 8. Ксюша сидела, (не)шевелясь от страха. 9. (Не)доглядев за кашей, повар её подпалил. 10. Пушок спал, (не)обращая внимания на шум.<br>Пояснения: в предложении 7 речь о болельщиках, которые очень бурно выражают чувства.',
  key:'Слитно: негодуя (годуя — нет), ненавидя (навидя — нет), недоумевая (доумевая — нет), невзлюбив (взлюбив — нет), неистовствуя (истовствуя — нет).<br>Слитно с приставкой недо-: недоглядев (= недосмотрел, не уследил).<br>Раздельно: не отрывая, не дослушав (дослушав — есть), не шевелясь (шевелясь — есть), не обращая.'},
 {n:49,l:4,st:2,task:'Раскрыть скобки. Объяснить написание: приставка недо- со значением «меньше нормы» или не + деепричастие с приставкой до- («не довести до конца»). Составить ещё одну пару предложений с таким различием.',
  obr:'Неделю он занимался, (не)досыпая. → недосыпая (спал меньше нормы). Он ушёл, (не)досмотрев фильм до конца. → не досмотрев (не довёл до конца).',
  body:'1. Перед соревнованиями спортсмен тренировался, (не)досыпая. 2. (Не)дочитав статью до конца, Оля вернула её в библиотеку. 3. Повар испортил кашу, (не)досолив её. 4. Рома вскочил из-за стола, (не)доев котлету. 5. (Не)дооценив соперника, команда проиграла. 6. (Не)дослушав объяснение, Геня поднял руку. 7. В походе мы немного (не)доедали, но были веселы. 8. (Не)допив чай, сторож пошёл встречать гостей.',
  key:'1. Недосыпая — недо- «меньше нормы» (спал меньше, чем нужно). 2. Не дочитав — не довела до конца (есть слова «до конца»). 3. Недосолив — посолил меньше, чем нужно. 4. Не доев — не съел до конца. 5. Недооценив — оценили ниже, чем нужно. 6. Не дослушав — не дослушал до конца. 7. Недоедали — глагол с недо- «меньше нормы» (то же правило, что у деепричастий). 8. Не допив — не допил до конца.<br>Примерная пара: Он рос слабым, недоедая в голодные годы. — Он убежал во двор, не доев обед.'},
 {n:50,l:4,st:2,task:'Раскрыть скобки. Объяснить, где предлог несмотря на (= вопреки), где деепричастие не смотря (= не глядя), где наречие нехотя (= неохотно). Проверить заменой.',
  obr:'(Не)смотря на ливень, мы пошли гулять. → Несмотря на ливень (= вопреки ливню) — предлог, слитно.',
  body:'1. (Не)смотря на мороз, ребятишки катались с горки. 2. Егор шёл, (не)смотря под ноги, и споткнулся. 3. Алёша (не)хотя встал с дивана. 4. (Не)смотря на усталость, лыжники дошли до вершины. 5. Лиза отвечала, (не)смотря в тетрадь. 6. Дружок (не)хотя отдал мячик. 7. (Не)смотря на поздний час, в окнах горел свет. 8. Ира прошла мимо, (не)смотря в нашу сторону.',
  key:'1. Несмотря на мороз (= вопреки морозу) — предлог. 2. Не смотря (= не глядя) под ноги — деепричастие. 3. Нехотя (= неохотно) — наречие. 4. Несмотря на усталость — предлог. 5. Не смотря (= не глядя) в тетрадь — деепричастие. 6. Нехотя — наречие. 7. Несмотря на поздний час — предлог. 8. Не смотря (= не глядя) — деепричастие.<br>Проверка: если можно заменить словом «вопреки» — пишется слитно; если можно заменить словами «не глядя» — раздельно.'},
 {n:51,l:4,st:2,task:'Вставить пропущенные буквы. Рядом записать неопределённую форму и форму прошедшего времени, по которым проверяется гласная перед -в, -вши. Гласную подчеркнуть.',
  obr:'Обид…в → обидеть, обидел → обидев.',
  body:'Посе…в рожь, прикле…в марку, понаде…вшись на удачу, замешк…вшись у двери, зате…в игру, выздоров…в после болезни, повес…в картину, раста…в на солнце, обезвред…в мину, посмотр…в в окошко, усво…в правило, разве…в сомнения, покрасн…в от смущения, засе…в поле, отча…вшись, присмотр…вшись.',
  key:'Посеяв (посеять, посеял), приклеив (приклеить), понадеявшись (понадеяться), замешкавшись (замешкаться), затеяв (затеять), выздоровев (выздороветь), повесив (повесить), растаяв (растаять), обезвредив (обезвредить), посмотрев (посмотреть), усвоив (усвоить), развеяв (развеять), покраснев (покраснеть), засеяв (засеять), отчаявшись (отчаяться), присмотревшись (присмотреться).<br>Перед -в, -вши пишется та же гласная, что перед -ть в неопределённой форме и перед -л в прошедшем времени.'},
 {n:52,l:4,st:3,task:'Вставить пропущенные буквы. Определить, причастие это или деепричастие (поставить вопрос). Объяснить написание: -сь или -ся, а или я после шипящих.',
  obr:'Улыба…, Алина подошла к нам. → Улыбаясь (что делая?) — деепричастие, -сь. Улыба…щаяся Алина → улыбающаяся (какая?) — причастие, -ся.',
  body:'1. Умыва…, Васька тёр лапкой мордочку. 2. Умывающ… Васька не заметил нас. 3. Дыш…, сынишка грел замёрзшие ладошки. 4. Шарик, дрож… от холода, жался к стене. 5. Вернувш… в город, сестра сразу позвонила подруге. 6. Вернувш…ся в город сестра позвонила подруге. 7. Слыш… шорох, ёжик свернулся клубком. 8. Олег бежал, крич… что-то на ходу. 9. Пятиклассники, держ… друг друга за руки, перешли ручеёк. 10. Оглянувш…, белка скрылась в дупле.',
  key:'1. Умываясь — деепричастие (что делая?), -сь. 2. Умывающийся — причастие (какой?), -ся. 3. Дыша — деепричастие, после ш — а. 4. Дрожа — деепричастие, после ж — а. 5. Вернувшись — деепричастие (что сделав?), -сь. 6. Вернувшаяся — причастие (какая?), -ся. 7. Слыша — деепричастие, после ш — а. 8. Крича — деепричастие, после ч — а. 9. Держа — деепричастие, после ж — а. 10. Оглянувшись — деепричастие, -сь.<br>У деепричастий постфикс всегда -сь, у причастий — всегда -ся.'},
 {n:53,l:4,st:3,task:'Раскрыть скобки. Распределить слова в три столбика: не с глаголами, не с причастиями, не с деепричастиями. Объяснить, почему с причастиями не пишется то слитно, то раздельно, а с деепричастиями и глаголами — почти всегда раздельно.',
  obr:'(Не)прочитанная книга — непрочитанная (полное причастие без зависимых слов — слитно); (не)прочитав газету — раздельно (деепричастие).',
  body:'1. (Не)решённая задача. 2. (Не)решив головоломку. 3. Задача (не)решена. 4. (Не)решённая Колей задача. 5. Коля (не)решил головоломку. 6. (Не)замечая луж. 7. (Не)замеченная ошибка. 8. Ошибка (не)замечена. 9. (Не)навидя ложь. 10. (Не)навидящий ложь человек. 11. (Не)закрыв ворота. 12. (Не)закрытая на ключ дверь. 13. Дверь (не)закрыли. 14. (Не)досыпая ночами.',
  key:'Глаголы: не решил, не закрыли — раздельно.<br>Причастия: нерешённая (полное, без зависимых слов — слитно); не решённая Колей (есть зависимое слово — раздельно); не решена, не замечена (краткие — раздельно); незамеченная (слитно); ненавидящий (без не не употребляется — слитно); не закрытая на ключ (есть зависимые слова — раздельно).<br>Деепричастия: не решив, не замечая, не закрыв — раздельно; ненавидя, недосыпая — слитно (без не не употребляется; недо-).<br>У полных причастий написание зависит от зависимых слов, а у деепричастий — как у глагола: раздельно, кроме слов без пары и слов с недо-.'},
 {n:54,l:4,st:3,task:'Переписать, раскрывая скобки. Объяснить слитное и раздельное написание не. Найти предложение, где не входит в состав предлога.',
  obr:'Каждый из нас думал про себя, (не)смея сообщить другому своих мыслей. → не смея — деепричастие, раздельно.',
  body:'1. Каждый из нас думал про себя, (не)смея сообщить другому своих мыслей. (А. С. Пушкин, «Капитанская дочка») 2. Вот мы, (не)видя ничего, уж и поссорились. (И. А. Гончаров, «Обломов») 3. Но Василий Иванович, (не)оборачиваясь, только рукой махнул и вышел. (И. С. Тургенев, «Отцы и дети») 4. Потом, (не)затягивая дела, оделся, надел на плеча шинель и вышел на улицу. (Н. В. Гоголь, «Шинель») 5. Отец глядел на меня молча, (не)смея верить самому себе. (А. С. Пушкин, «Капитанская дочка») 6. Аркадий глядел на дорогу и улыбался, сам (не)зная чему. (И. С. Тургенев, «Отцы и дети») 7. Мать, (не)годуя, рассказывала о моих подвигах деду… (М. Горький, «Детство») 8. (Не)смотря на предсказания, башкирцы не возмущались. (А. С. Пушкин, «Капитанская дочка») 9. Хаджи-Мурат, (не)доумевая, покачал головой… (Л. Н. Толстой, «Хаджи-Мурат»)<br>Пояснения: на плеча — устаревшая форма: на плечи.',
  key:'1. Не смея. 2. Не видя. 3. Не оборачиваясь. 4. Не затягивая. 5. Не смея. 6. Не зная. 7. Негодуя — без не не употребляется. 8. Несмотря на — предлог (= вопреки предсказаниям), слитно. 9. Недоумевая — без не не употребляется.<br>Остальные деепричастия употребляются без не, поэтому пишутся раздельно.'},
 {n:55,l:4,st:3,task:'Вставить пропущенные буквы, раскрыть скобки. Над каждым деепричастием указать вид. Объяснить все орфограммы деепричастий: гласную перед -в, -вши, а после шипящих, -сь, не.',
  obr:'Понаде…вшись на удачу, Тимур (не)взял зонт. → Понадеявшись (сов. в., понадеяться) …не взял — глагол с не раздельно.',
  body:'1. Засе…в грядку морковью, Анна Петровна полила её из лейки. 2. Мальчишки шли по мосту, (не)спеша и держ… друг друга за руки. 3. Зате…в уборку, мы (не)заметили, как пролетел день. 4. Барсик лежал на подоконнике, щур…сь от солнца. 5. (Не)доумева…, Тимоша смотрел на фокусника. 6. Прикле…в последнюю марку, Толя закрыл альбом. 7. Выздоров…в, Надя вернулась на тренировку. 8. Отча…вшись найти тетрадь, Люда заглянула под кровать. 9. Ученица решала пример у доски, (не)смотря в учебник. 10. (Не)смотря на ветер, рыбаки вышли в море.',
  key:'1. Засеяв (сов. в.; засеять). 2. Не спеша (несов. в.; раздельно), держа (несов. в.; после ж — а). 3. Затеяв (сов. в.; затеять); не заметили — глагол. 4. Щурясь (несов. в.; -сь). 5. Недоумевая (несов. в.; без не не употребляется — слитно). 6. Приклеив (сов. в.; приклеить). 7. Выздоровев (сов. в.; выздороветь). 8. Отчаявшись (сов. в.; отчаяться; -сь). 9. Не смотря в учебник (несов. в.; = не глядя — раздельно). 10. Несмотря на — предлог (= вопреки), слитно.'},
 {n:56,l:4,st:4,task:'Распределительный диктант. Распределить слова и сочетания в два столбика: с не слитно и с не раздельно. В каждом случае указать часть речи (глагол, причастие, деепричастие, предлог, наречие) и правило.',
  body:'(Не)годуя на обидчика; (не)досоленный суп; (не)дослушав рассказ до конца; (не)взяв сдачу; (не)взлюбив соседа; (не)смотря на жару; (не)смотря вниз; (не)хотя согласиться; (не)доумевающий взгляд; (не)понимая вопроса; (не)понятый друзьями; (не)понят друзьями; (не)дооценивать силы; (не)доделав работу до конца; (не)навидеть ложь; (не)спеша закончить; (не)замеченная нами ошибка; (не)замеченная ошибка.',
  key:'Слитно: негодуя (деепр.; без не не употр.); недосоленный (прич. с недо- «меньше нормы»); невзлюбив (деепр.; без не не употр.); несмотря на (предлог); нехотя (наречие); недоумевающий (прич.; без не не употр.); недооценивать (глагол с недо-); ненавидеть (глагол; без не не употр.); незамеченная ошибка (полное прич. без зависимых слов).<br>Раздельно: не дослушав до конца (деепр.; не довёл до конца), не взяв (деепр.), не смотря вниз (деепр. = не глядя), не понимая (деепр.), не понятый друзьями (прич. с зависимыми словами), не понят (краткое прич.), не доделав до конца (деепр.; не довёл до конца), не спеша (деепр.), не замеченная нами (прич. с зависимыми словами).'},
 {n:57,l:4,st:4,task:'Объяснительный диктант. Записать предложения, вставляя буквы и раскрывая скобки. Устно (или письменно в скобках) объяснить каждую орфограмму в деепричастиях: не, гласную перед -в и -вши, а после шипящих, -сь, буквы в деепричастиях придя и давая.',
  body:'1. При(й)дя на вокзал заранее, мы долго ходили по перрону, то и дело поглядывая на часы. 2. Вста…я по утрам, дед первым делом смотрит на градусник. 3. (Не)доумева…, Мурзик разглядывал своё отражение в зеркале. 4. Обид…вшись на Рустама, Полина весь вечер молчала. 5. Пёс бежал, высун…в язык и (не)обращая внимания на прохожих. 6. Учитель объяснял правило, зада…я нам вопросы. 7. Рустам сидел, слуш… музыку и (не)смотря по сторонам. 8. (Не)навид… ложь, герой рассказа всегда говорил правду. 9. Посе…в семена, одноклассники полили грядку. 10. Мы помчались к речке, (не)дожд…вшись остальных.',
  key:'1. Придя (без й, как «придут»); поглядывая (поглядывают → -я). 2. Вставая (корень ста- с -ва-: от основы инфинитива). 3. Недоумевая (без не не употребляется). 4. Обидевшись (обидеться — обиделся; -сь). 5. Высунув (высунуть — высунул); не обращая (раздельно). 6. Задавая (корень да- с -ва-). 7. Слушая; не смотря (= не глядя) по сторонам — раздельно. 8. Ненавидя (без не не употребляется; после д — я). 9. Посеяв (посеять — посеял). 10. Не дождавшись (раздельно; дождаться — дождался).'},
 {n:58,l:4,st:4,task:'Найти и исправить ошибки в тексте ученика (орфографические и одну грамматическую). Объяснить каждую ошибку. Сколько ошибок нашлось?',
  body:'Прийдя из школы, я сразу сел за уроки, неотвлекаясь на телефон. Быстро решив задачи и выучив правило, я взялся за сочинение. Задумываяся над каждым словом, я писал медленно, но недоделав работу до конца, вспомнил о тренировке. Собрав сумку и обул кроссовки, побежал в спортзал. Тренер, увидев меня, улыбнулся и, дая мне задание, похлопал по плечу. Нехотя признаю, что тренировка прошла лучше, чем уроки: занимаясь в зале, я неуставал, а за столом устал быстро. Вернувшись с тренировки, я всё-таки дописал сочинение, несмотря на усталость.',
  key:'Ошибки: 1) прийдя → придя; 2) неотвлекаясь → не отвлекаясь (раздельно); 3) задумываяся → задумываясь (у деепричастий -сь); 4) недоделав работу до конца → не доделав (не довёл до конца); 5) «Собрав сумку и обул кроссовки» — деепричастие однородно со сказуемым: исправить «Собрав сумку и обув кроссовки» (это ошибка употребления — урок 5); 6) дая → давая (корень да- с -ва-: от основы инфинитива); 7) неуставал → не уставал (не с глаголом раздельно). Всего 7 исправлений.<br>Верно написаны: решив, выучив, увидев, нехотя (наречие), занимаясь, вернувшись, несмотря на (предлог).'},
 {n:59,l:4,st:4,task:'Составить пары предложений, показывающие разницу в написании. Объяснить, почему в одном предложении пишется слитно, а в другом раздельно. Пары: недосыпая — не досмотрев (до конца); недооценив — не доиграв (до конца); несмотря на — не смотря; нехотя — не спеша; ненавидя — не любя.',
  body:'Опорные слова: экзамены, хоккейный матч, снегопад, витрина, уборка, капуста, соперник, сериал.',
  key:'Примерные ответы. 1) Перед экзаменами Костя занимался, недосыпая (спал меньше нормы). — Костя ушёл, не досмотрев сериал до конца. 2) Недооценив соперника, команда проиграла (оценили ниже, чем нужно). — Мы ушли с катка, не доиграв хоккейный матч до конца. 3) Несмотря на снегопад, мы пошли гулять (предлог = вопреки). — Он шёл, не смотря на витрины (деепричастие = не глядя). 4) Даша нехотя взялась за уборку (наречие = неохотно). — Няня шла по рынку не спеша (деепричастие с не — раздельно). 5) Ненавидя капусту, Андрюша отодвинул тарелку (без не «навидя» нет — слитно). — Не любя капусту, Андрюша отодвинул тарелку («любя» есть — раздельно).<br>Критерии: в каждой паре верное написание и верное объяснение; предложения естественные; при обороте — запятые.'},
 {n:60,l:4,st:3,task:'Переписать, вставляя пропущенные буквы. Объяснить написание гласной перед -в, -вши, а после шипящих и постфикса -сь. Над деепричастиями указать вид.',
  obr:'Увид…в это, капитан плюнул и топнул ногой. → Увидев (сов. в.): увидеть — увидел.',
  body:'1. Увид…в это, капитан плюнул и топнул ногой. (М. Ю. Лермонтов, «Герой нашего времени») 2. Лаврецкий посмотрел ей вслед и, понур…в голову, отправился назад по улице. (И. С. Тургенев, «Дворянское гнездо») 3. Наигр…вшись, волчата пошли в яму и легли спать. (А. П. Чехов, «Белолобый») 4. Осмотр…в обе стороны конюшни и похвал…в в них чистоту, отец вышел опять на двор. (С. Т. Аксаков, «Детские годы Багрова-внука») 5. Лунный свет, прорез…вшись сквозь чащу деревьев, скользил по резьбе ворот слабыми фосфорическими пятнами. (А. И. Куприн, «Белый пудель») 6. Лодыжкин, кряхт…, вскинул шарманку за плечи. (А. И. Куприн, «Белый пудель») 7. Холодно поздоров…вшись и приглас…в сесть Чернышёва, Николай уставился на него. (Л. Н. Толстой, «Хаджи-Мурат») 8. Тётка, (не)вынос… музыки, беспокойно задвигалась на стуле и завыла. (А. П. Чехов, «Каштанка»)<br>Пояснения: понурить голову — опустить её; фосфорический — слабо светящийся.',
  key:'1. Увидев (сов. в.; увидеть). 2. Понурив (сов. в.; понурить). 3. Наигравшись (сов. в.; наиграться; -сь). 4. Осмотрев (сов. в.; осмотреть), похвалив (сов. в.; похвалить). 5. Прорезавшись (сов. в.; прорезаться; -сь). 6. Кряхтя (несов. в.; они кряхтят → -я). 7. Поздоровавшись (сов. в.; поздороваться), пригласив (сов. в.; пригласить). 8. Не вынося (несов. в.; не — раздельно; выносят → -я).'},
 {n:61,l:4,st:5,task:'Тонкость. 1) Объяснить разницу в написании и значении: обессилев — обессилив; обезлюдев — обезлюдив. Составить с каждым деепричастием предложение. 2) У поэтов XIX века встречаются деепричастия на -ся. Найти их и записать по современным нормам. Почему поэты их использовали?',
  body:'1) Обессилеть — обессилить; обезлюдеть — обезлюдить. 2) а) Немного лет тому назад, / Там, где, сливаяся, шумят, / Обнявшись, будто две сестры, / Струи Арагвы и Куры, / Был монастырь. (М. Ю. Лермонтов, «Мцыри») б) Люблю грозу в начале мая, / Когда весенний, первый гром, / Как бы резвяся и играя, / Грохочет в небе голубом. (Ф. И. Тютчев, «Весенняя гроза»)',
  key:'1) Обессилеть — самому стать бессильным: Обессилев от жары, путник сел в тень. Обессилить — сделать бессильным кого-то: Обессилив противника, борец перешёл в атаку. Обезлюдеть — опустеть: Обезлюдев к осени, дачный посёлок затих. Обезлюдить — сделать безлюдным: Обезлюдив пляж, ливень разогнал отдыхающих. Гласная перед -в — та же, что перед -ть, поэтому сначала нужно понять, от какого глагола образовано деепричастие.<br>2) Сливаяся — сливаясь; резвяся — резвясь. В XIX веке в стихах ещё встречалась старая полная форма -ся; поэты брали её ради размера: лишний слог (слива-я-ся) нужен для ритма строки. Сейчас у деепричастий только -сь. Обнявшись, играя — современные формы.'},
 {n:62,l:4,st:5,os:'диктант',task:'Диктант. Записать текст, вставляя буквы и раскрывая скобки, расставить запятые при деепричастных оборотах. Подчеркнуть деепричастия и надписать над ними вид. Выписать слова с не и объяснить их написание.',
  body:'Зимой в парке. При(й)дя в парк после уроков мы сразу побежали к горке. Малыши катались на санках весело крич… и (не)переставая толкать друг друга. Мы взяли ледянки и (не)дожд…вшись своей очереди съехали с другого края. Сделав несколько кругов я (не)хотя отдал ледянку младшему Илье. Он схватил её и (не)оглядываясь помчался к горке. Посмотр…в на часы и (не)веря своим глазам мы стали собираться на станцию. Отряхн…в варежки от снега и попрощ…вшись с друзьями мы пошли по аллее не спеша.',
  key:'Придя в парк после уроков, мы сразу побежали к горке. Малыши катались на санках, весело крича и не переставая толкать друг друга. Мы взяли ледянки и, не дождавшись своей очереди, съехали с другого края. Сделав несколько кругов, я нехотя отдал ледянку младшему Илье. Он схватил её и, не оглядываясь, помчался к горке. Посмотрев на часы и не веря своим глазам, мы стали собираться на станцию. Отряхнув варежки от снега и попрощавшись с друзьями, мы пошли по аллее не спеша.<br>Не: не переставая, не дождавшись, не оглядываясь, не веря — деепричастия, раздельно; нехотя — наречие (= неохотно). «Не спеша» в конце — деепричастие в роли наречия, без запятых. Виды: придя, сделав, посмотрев, отряхнув, попрощавшись, не дождавшись — сов. в.; крича, не переставая, не оглядываясь, не веря, не спеша — несов. в.'},
// ── Урок 5. Как правильно употреблять деепричастия
 {n:63,l:5,st:1,task:'Найти в каждом предложении сказуемое и деепричастие. Ответить на вопросы: кто выполняет главное действие? кто выполняет добавочное действие? Убедиться, что это одно и то же лицо. Подлежащее подчеркнуть одной чертой.',
  obr:'Подъезжая к станции, я увидел товарища. → Кто увидел? — я. Кто подъезжал? — я. Одно лицо — предложение построено верно.',
  body:'1. Выбежав на поляну, Дружок замер от удивления. 2. Склонившись над картой, капитан прокладывал курс. 3. Юля, закончив рисунок, показала его Кате. 4. Мы шли по аллее, разглядывая жёлтые клёны. 5. Выслушав ответ, учительница кивнула. 6. Белка, заметив орех, спустилась с ветки. 7. Проснувшись, я сразу вспомнил о поездке. 8. Самолёт, набрав высоту, повернул на север.',
  key:'1. Замер — Дружок; выбежав — Дружок. 2. Прокладывал — капитан; склонившись — капитан. 3. Показала — Юля; закончив — Юля. 4. Шли — мы; разглядывая — мы. 5. Кивнула — учительница; выслушав — учительница. 6. Спустилась — белка; заметив — белка. 7. Вспомнил — я; проснувшись — я. 8. Повернул — самолёт; набрав высоту — самолёт.<br>Во всех предложениях оба действия выполняет подлежащее — так и должно быть.'},
 {n:64,l:5,st:2,task:'Выписать номера предложений, в которых деепричастие употреблено с ошибкой. Для каждого объяснить: кто выполняет главное действие, а кто — действие деепричастия?',
  obr:'Открыв окошко, в комнату ворвался ветер. → Ошибка: ворвался ветер, а окошко открыл кто-то другой.',
  body:'1. Подходя к дому, я услышал знакомую песню. 2. Подходя к дому, мне послышалась знакомая песня. 3. Открыв холодильник, тётя достала молоко. 4. Открыв холодильник, на пол упала банка. 5. Прочитав статью, Боря написал отзыв. 6. Прочитав статью, у Бори появилось много вопросов. 7. Гуляя по парку, мы встретили одноклассника. 8. Гуляя по парку, нас застал ливень. 9. Вернувшись из отпуска, папа показал нам фотографии. 10. Вернувшись из отпуска, папе подарили сувенир.',
  key:'С ошибкой: 2 (послышалась песня, а подходил я), 4 (упала банка, а открывала тётя или кто-то другой), 6 (появились вопросы, а читал Боря), 8 (застал ливень, а гуляли мы), 10 (подарили другие люди, а вернулся папа).<br>Верно: 1, 3, 5, 7, 9 — оба действия выполняет подлежащее.'},
 {n:65,l:5,st:2,task:'Исправить ошибки двумя способами: 1) сделать подлежащим того, кто выполняет действие деепричастия; 2) заменить деепричастный оборот придаточной частью со словом «когда».',
  obr:'Выйдя на улицу, мне стало холодно. → 1) Выйдя на улицу, я замёрз. 2) Когда я вышел на улицу, мне стало холодно.',
  body:'1. Подойдя к окошку, мне стал виден весь двор. 2. Читая эту сказку, Гоше стало страшно. 3. Сев в троллейбус, у Риты зазвонил телефон. 4. Возвращаясь из школы, меня догнал друг. 5. Получив пятёрку, у Димы поднялось настроение. 6. Войдя в лес, нас окружила тишина.',
  key:'1. 1) Подойдя к окошку, я увидел весь двор. 2) Когда я подошёл к окошку, мне стал виден весь двор. 2. 1) Читая эту сказку, Гоша испугался. 2) Когда Гоша читал эту сказку, ему стало страшно. 3. 1) Сев в троллейбус, Рита услышала звонок телефона. 2) Когда Рита села в троллейбус, у неё зазвонил телефон. 4. 1) Возвращаясь из школы, я услышал, что меня догоняет друг. 2) Когда я возвращался из школы, меня догнал друг. 5. 1) Получив пятёрку, Дима повеселел. 2) Когда Дима получил пятёрку, у него поднялось настроение. 6. 1) Войдя в лес, мы оказались в тишине. 2) Когда мы вошли в лес, нас окружила тишина.<br>Критерии: в способе 1 подлежащее выполняет оба действия; в способе 2 в придаточной части есть своё подлежащее.'},
 {n:66,l:5,st:2,task:'Закончить предложения так, чтобы действие деепричастия и действие сказуемого выполнял один и тот же человек или предмет. Подлежащее подчеркнуть одной чертой.',
  obr:'Подъезжая к школе, … → Подъезжая к школе, я заметил на крыльце директора.',
  body:'1. Сдав последний экзамен, … 2. Поднимаясь в гору, … 3. Услышав звонок в калитку, … 4. Рассматривая старые фотографии, … 5. Испугавшись грозы, … 6. Добравшись до вершины, … 7. Перелистывая журнал, … 8. Набрав полное лукошко грибов, …',
  key:'Примерные ответы: 1. Сдав последний экзамен, Света поехала на море. 2. Поднимаясь в гору, путешественники часто останавливались. 3. Услышав звонок в калитку, прабабушка пошла открывать. 4. Рассматривая старые фотографии, Катя вспоминала детство. 5. Испугавшись грозы, Пушок спрятался под кровать. 6. Добравшись до вершины, альпинисты установили флаг. 7. Перелистывая журнал, я наткнулся на интересную статью. 8. Набрав полное лукошко грибов, сторож повернул в лагерь.<br>Критерий: подлежащее выполняет действие деепричастия; неверно: «Сдав экзамен, мне стало легко».'},
 {n:67,l:5,st:3,task:'Заменить придаточную часть деепричастным оборотом там, где это возможно. Объяснить, почему в некоторых предложениях замена невозможна.',
  obr:'Когда отец вернулся с работы, он сел ужинать. → Вернувшись с работы, отец сел ужинать (одно лицо). Когда Галя вернулась, мы сели ужинать — замена невозможна: разные лица.',
  body:'1. Когда Оля закончила рисунок, она повесила его на стену. 2. Когда пошёл дождь, мы спрятались под навес. 3. Когда я проснулся, мне стало весело. 4. Если ты перейдёшь мост, ты увидишь мельницу. 5. Когда учитель вошёл в класс, пятиклассники встали. 6. Так как Миша опоздал на трамвай, он пошёл пешком. 7. Когда мы подошли к речке, нам захотелось искупаться. 8. Когда Ира читала, она всегда грызла яблоко.',
  key:'1. Закончив рисунок, Оля повесила его на стену. 2. Нельзя: дождь пошёл сам, а спрятались мы — разные лица. 3. Нельзя: главная часть безличная (мне стало весело), подлежащего нет. 4. Перейдя мост, ты увидишь мельницу. 5. Нельзя: вошёл учитель, а встали пятиклассники. 6. Опоздав на трамвай, Миша пошёл пешком. 7. Нельзя: главная часть безличная (нам захотелось); можно перестроить: Подойдя к речке, мы захотели искупаться. 8. Читая, Ира всегда грызла яблоко.'},
 {n:68,l:5,st:3,task:'Заменить деепричастный оборот придаточной частью со словами когда, если, потому что, так как. Подобрать слово по смыслу оборота (время, условие, причина).',
  obr:'Устав после похода, мальчишки рано легли спать. → Мальчишки рано легли спать, потому что устали после похода (причина).',
  body:'1. Вернувшись с прогулки, мы сели пить чай. 2. Испугавшись собаки, Рыжик забрался на дерево. 3. Выучив правило, ты легко решишь загадку. 4. Подходя к дому, Аня увидела в окне Мадину. 5. Не зная дороги, мы долго плутали по роще. 6. Поднявшись на башню, туристы увидели весь город.',
  key:'1. Когда мы вернулись с прогулки, то сели пить чай (время). 2. Рыжик забрался на дерево, потому что испугался собаки (причина). 3. Если ты выучишь правило, ты легко решишь загадку (условие). 4. Когда Аня подходила к дому, она увидела в окне Мадину (время). 5. Мы долго плутали по роще, так как не знали дороги (причина). 6. Когда туристы поднялись на башню, они увидели весь город (время).<br>Деепричастие несовершенного вида передаётся глаголом несовершенного вида (подходила), совершенного — совершенного (вернулись, поднялись).'},
 {n:69,l:5,st:3,task:'Определить, верно ли построены предложения без подлежащего. Для верных указать, по какому слову видно, кто выполняет действие деепричастия (повелительное наклонение, окончание глагола, неопределённая форма). Неверные исправить.',
  obr:'Уходя, гасите свет. → Верно: «гасите» — повелительное наклонение, уходите и гасите вы.',
  body:'1. Переходя улицу, нужно смотреть по сторонам. 2. Переходя улицу, мне стало страшно. 3. Прочитав повесть, верни её в библиотеку. 4. Уезжая надолго, надо закрыть окна. 5. Получив письмо, сразу отвечаю. 6. Купаясь в речке, было очень весело. 7. Поднимаясь по лестнице, держитесь за перила. 8. Глядя на звёзды, мне стало грустно. 9. Закончив работу, можно отдохнуть. 10. Войдя в музей, сразу стало тихо.',
  key:'Верно: 1 (нужно смотреть — тот, кто переходит); 3 (верни — ты); 4 (надо закрыть — тот, кто уезжает); 5 (отвечаю — я); 7 (держитесь — вы); 9 (можно отдохнуть — тот, кто закончил).<br>С ошибкой: 2 — Переходя улицу, я испугался. 6 — Купаясь в речке, мы очень веселились. 8 — безличное предложение со словом «мне»: Глядя на звёзды, я загрустил / Когда я глядел на звёзды, мне стало грустно. 10 — Войдя в музей, мы сразу заговорили тише / Когда мы вошли в музей, сразу стало тихо.'},
 {n:70,l:5,st:3,task:'Выбрать из скобок деепричастие, которое подходит по смыслу (вид должен соответствовать порядку действий). Записать предложения, объяснить выбор.',
  obr:'(Решая, Решив) головоломку, Миша сдал тетрадь. → Решив: сдать можно только решённую головоломку — сначала решил, потом сдал.',
  body:'1. (Гуляя, Погуляв) по парку, мы любовались клёнами. 2. (Надевая, Надев) куртку, Гриша вышел на улицу. 3. (Читая, Прочитав) сказку вслух, соседка меняла голос за каждого героя. 4. (Поднимаясь, Поднявшись) на вершину, альпинисты установили на ней флаг. 5. (Переходя, Перейдя) дорогу, пешеход внимательно смотрел по сторонам. 6. (Собирая, Собрав) вещи в рюкзак, Аня то и дело заглядывала в список. 7. (Закрывая, Закрыв) дверь на ключ, Нина отправилась на работу. 8. (Убирая, Убрав) в комнате, Надя села отдохнуть.',
  key:'1. Гуляя — одновременно (любовались во время прогулки). 2. Надев — сначала надел, потом вышел. 3. Читая — меняла голос во время чтения. 4. Поднявшись — флаг ставят, когда подъём закончен. 5. Переходя — смотрел по сторонам во время перехода. 6. Собирая — заглядывала в список, пока собирала. 7. Закрыв — сначала закрыла, потом отправилась. 8. Убрав — сначала убрала, потом села отдохнуть.'},
 {n:71,l:5,st:4,task:'Распределить предложения по типам ошибок: а) действия выполняют разные лица; б) безличное предложение без подлежащего; в) предмет сам не выполняет действия (сказуемое на -ся); г) деепричастие соединено со сказуемым союзом «и»; д) оборот однороден с придаточной частью. Тип в) — частный случай разных лиц: проверять его первым. Исправить каждое предложение.',
  body:'1. Закончив уборку, комната засияла чистотой. 2. Катаясь на коньках, мне стало жарко. 3. Готовясь к празднику, ёлка наряжалась всей семьёй. 4. Ребятишки сидели у костра и греясь. 5. Вернувшись на дачу и когда поужинал, Федя сел за компьютер. 6. Подъезжая к городу, нам открылся прекрасный вид. 7. Отправляясь в поход, палатки проверялись вечером. 8. Анна Петровна вязала носки и напевая. 9. Проснувшись рано и когда умылся, Коля вышел в сад. 10. Решая задачу, мне стало ясно, в чём ошибка.',
  key:'а) 1 — Закончив уборку, мы любовались чистой комнатой. 6 — Когда мы подъезжали к городу, нам открылся прекрасный вид. б) 2 — Катаясь на коньках, я разогрелся. 10 — Решая задачу, я понял, в чём ошибка. в) 3 — Готовясь к празднику, мы всей семьёй наряжали ёлку. 7 — Отправляясь в поход, туристы проверяли палатки вечером. г) 4 — Ребятишки сидели у костра и грелись (или: сидели у костра, греясь). 8 — Анна Петровна вязала носки и напевала (или: вязала носки, напевая). д) 5 — Вернувшись на дачу и поужинав, Федя сел за компьютер. 9 — Проснувшись рано и умывшись, Коля вышел в сад.'},
 {n:72,l:5,st:4,task:'Задание в формате ЕГЭ (задание 8). Установить соответствие между грамматическими ошибками и предложениями, в которых они допущены: к каждой позиции первого столбца подобрать позицию из второго. Записать ответ цифрами, например: А — 3. Предложения без ошибок назвать отдельно.',
  body:'Ошибки: А) нарушение в построении предложения с деепричастным оборотом; Б) нарушение в построении предложения с причастным оборотом; В) ошибка в построении предложения с однородными членами; Г) нарушение видо-временной соотнесённости глагольных форм; Д) неправильное употребление падежной формы существительного с предлогом.<br>Предложения: 1) Одноклассники, участвовавшие в олимпиаде, получили грамоты. 2) Благодаря настойчивости тренера команда вышла в финал. 3) Прочитав повесть, мне захотелось побывать в этих местах. 4) Благодаря усилий учеников сад был приведён в порядок. 5) Мы любим и гордимся своим городом. 6) Отряд, вернувшиеся из похода, отдыхал в лагере. 7) Когда Стёпа вернулся к бабушке, он садится за уроки. 8) Сделав уроки, Даша пошла гулять. 9) Выпавший ночью снег укрыл поля.',
  key:'А — 3 (прочитал «я», а «мне захотелось» — безличное; верно: Прочитав повесть, я захотел побывать в этих местах). Б — 6 (причастие не согласовано с определяемым словом: отряд, вернувшийся из похода). В — 5 (любить что? гордиться чем? — однородным сказуемым нужно своё дополнение: Мы любим свой город и гордимся им). Г — 7 (вернулся — прошедшее, садится — настоящее: …он сел за уроки). Д — 4 (благодаря чему? — благодаря усилиям учеников).<br>Без ошибок: 1, 2, 8, 9.'},
 {n:73,l:5,st:4,task:'Отредактировать текст ученика: найти ошибки в употреблении деепричастий и деепричастных оборотов, исправить их и записать исправленный текст.',
  body:'Наш поход. Собравшись рано утром, рюкзаки были уложены за полчаса. Выйдя из дома, нас уже ждал автобус. Подъезжая к бору, мне захотелось петь. Мы шли по тропинке и разглядывая деревья. Дойдя до озера и когда поставили палатки, школьники пошли купаться. Купаясь в тёплой воде, нам было очень весело. Вечером, сидя у костра, мы пели песни и смотрели на звёзды. Вернувшись в город, поход ещё долго вспоминался всем нам.',
  key:'Примерный исправленный текст. Наш поход. Собравшись рано утром, мы уложили рюкзаки за полчаса. Когда мы вышли из дома, нас уже ждал автобус. Подъезжая к бору, я запел (или: Когда мы подъезжали к бору, мне захотелось петь). Мы шли по тропинке, разглядывая деревья. Дойдя до озера и поставив палатки, школьники пошли купаться. Купаясь в тёплой воде, мы очень веселились. Вечером, сидя у костра, мы пели песни и смотрели на звёзды (ошибки нет). Вернувшись в город, мы ещё долго вспоминали поход.<br>Ошибки: разные лица (2-е предложение), сказуемое на -ся / страдательное — предмет сам не действует (1, 8), безличные предложения (3, 6), деепричастие однородно со сказуемым (4), оборот однороден с придаточной (5).'},
 {n:74,l:5,st:4,task:'Соединить два предложения в одно, заменив одно из сказуемых деепричастным оборотом. Если это невозможно, объяснить почему и соединить предложения по-другому (с союзом и, когда, потому что).',
  obr:'Рома открыл книгу. Он увидел закладку. → Открыв книгу, Рома увидел закладку.',
  body:'1. Ксюша вышла во двор. Она позвала подругу. 2. Катя вошла в комнату. Кот спрыгнул с дивана. 3. Алёша вымыл посуду. Он сел смотреть фильм. 4. Ученики сдали тетради. Учитель стал их проверять. 5. Мы поднялись на холм. Нам открылся вид на реку. 6. Иван Петрович взял удочки. Он пошёл к реке. 7. Начался дождь. Мы раскрыли зонты. 8. Бобик увидел кошку. Он громко залаял.',
  key:'1. Выйдя во двор, Ксюша позвала подругу. 2. Нельзя: разные лица (вошла Катя, спрыгнул кот); можно: Когда Катя вошла в комнату, кот спрыгнул с дивана. 3. Вымыв посуду, Алёша сел смотреть фильм. 4. Нельзя: сдали ученики, проверяет учитель; можно: Когда ученики сдали тетради, учитель стал их проверять. 5. Нельзя: вторая часть безличная; можно: Поднявшись на холм, мы увидели реку / Когда мы поднялись на холм, нам открылся вид на реку. 6. Взяв удочки, Иван Петрович пошёл к реке. 7. Нельзя: дождь начался сам; можно: Когда начался дождь, мы раскрыли зонты. 8. Увидев кошку, Бобик громко залаял.'},
 {n:75,l:5,st:5,task:'Тонкость. Объяснить, в чём ошибка (или особенность) употребления деепричастий в отрывках. Почему в первом случае это намеренная ошибка, а во втором — особенность языка XIX века? Переписать оба предложения так, как они были бы построены сегодня.',
  body:'1. «Подъезжая к сией станцыи и глядя на природу в окно, у меня слетела шляпа. И. Ярмонкин». (А. П. Чехов, «Жалобная книга») 2. Далеко от Украинского края, проехавши Польшу, минуя и многолюдный город Лемберг, идут рядами высоковерхие горы. (Н. В. Гоголь, «Страшная месть»)<br>Пояснения: Лемберг — старое название города Львова.',
  key:'1. Запись в жалобной книге сделал малограмотный пассажир: Чехов нарочно сохранил его ошибки (сией станцыи, шляпа «подъезжает» к станции), чтобы посмеяться над героем. Ошибка — разные лица: подъезжал пассажир, а слетела шляпа. Сегодня: Когда я подъезжал к этой станции и смотрел в окно на природу, у меня слетела шляпа.<br>2. Деепричастия «проехавши», «минуя» относятся не к подлежащему (горы), а к путнику, который смотрит на горы; так писали в XIX веке, особенно в описаниях дороги. «Проехавши» — устаревшая форма на -вши (сейчас — проехав). Сегодня: Если проехать Польшу, миновать многолюдный Лемберг, то далеко от Украинского края увидишь высокие горы, которые тянутся рядами.'},
 {n:76,l:5,st:4,task:'Задание в формате итогового теста. Выписать номера предложений, в которых нет грамматических ошибок. Ошибочные предложения исправить.',
  body:'1. Окончив школу, Тимур поступил в институт. 2. Окончив школу, Тимуру подарили часы. 3. Рассматривая картину, у меня возникло много вопросов. 4. Рассматривая картину, я задал экскурсоводу много вопросов. 5. Отправляясь в путь, надо проверить, всё ли взято. 6. Подняв руку, ученик ответил на вопрос учителя. 7. Сидя у окна, мне было видно всю улицу. 8. Услышав шорох, ёж свернулся клубком. 9. Разбирая старые вещи, Верой Ивановной был найден альбом. 10. Возвращаясь в деревню, нужно не забыть купить хлеб.',
  key:'Без ошибок: 1, 4, 5, 6, 8, 10.<br>Исправления: 2 — Когда Тимур окончил школу, ему подарили часы. 3 — Рассматривая картину, я задумался о многом. 7 — Сидя у окна, я видел всю улицу. 9 — Разбирая старые вещи, Вера Ивановна нашла альбом.'},
 {n:77,l:5,st:5,os:'сочинение',task:'Написать сочинение-миниатюру «Неожиданная встреча» (6–8 предложений). Условия: 1) употребить не меньше пяти деепричастных оборотов (в том числе с деепричастиями разного вида); 2) одно предложение — без подлежащего, но с правильным оборотом (повелительное наклонение или «нужно, надо» + неопределённая форма); 3) после написания проверить каждое предложение по алгоритму «кто делает главное действие — кто делает добавочное» и записать результат проверки на полях.',
  body:'Опорные слова: идти по улице, заметить, обернуться, узнать, обрадоваться, договориться, попрощаться.',
  key:'Критерии: пять и больше оборотов; есть оба вида; одно верное предложение без подлежащего; во всех остальных подлежащее выполняет действие деепричастия; запятые при оборотах.<br>Образец: Возвращаясь из школы, я заметил на остановке знакомую фигуру. Подойдя ближе, я узнал своего старого друга Сашу. Саша, обернувшись на мой голос, радостно засмеялся. Перебивая друг друга, мы стали рассказывать новости. Оказалось, что Саша, переехав в наш район, теперь будет учиться в соседней школе. Договорившись встретиться в субботу, мы попрощались. Встретив старого друга, не забудьте сразу записать его новый номер телефона!'},
 {n:78,l:5,st:3,task:'Объяснить, почему предложения звучат смешно: описать картинку, которая получается, если понимать их буквально. Исправить предложения.',
  obr:'Купаясь в реке, меня укусил комар. → Получается, что в реке купался комар. Исправление: Когда я купался в реке, меня укусил комар.',
  body:'1. Убегая от собаки, у Егора слетела кепка. 2. Сидя на ветке, мы увидели белку. 3. Зевая во весь рот, урок показался мне длинным. 4. Подлетая к гнезду, птенцы встретили маму-ласточку. 5. Помыв голову, фен сломался. 6. Плавая в аквариуме, мы наблюдали за рыбками.',
  key:'1. Кепка убегала от собаки. — Когда Егор убегал от собаки, у него слетела кепка. 2. На ветке сидели мы. — Мы увидели белку, сидевшую на ветке / Мы увидели белку, которая сидела на ветке. 3. Зевал урок. — Зевая во весь рот, я с трудом дождался конца длинного урока. 4. Подлетали птенцы. — Когда ласточка подлетала к гнезду, птенцы встретили её писком. 5. Голову мыл фен. — Когда я помыл голову, фен сломался. 6. В аквариуме плавали мы. — Мы наблюдали за рыбками, плавающими в аквариуме.'},
// ── Урок 6. Морфологический разбор. Повторение
 {n:79,l:6,st:2,task:'Выполнить морфологический разбор выделенных деепричастий по плану: 1. Часть речи, общее значение; глагол, от которого образовано, и как образовано. 2. Вид, переходность, возвратность. 3. К какому слову относится; синтаксическая роль.',
  obr:'Школьник бежал по тропинке, размахивая портфелем. Размахивая:<br>1. Деепричастие, обозначает добавочное действие: бежал (что делая?) размахивая. Образовано от глагола размахивать: основа настоящего времени (размахива-ют) + суффикс -я.<br>2. Несов. в., неперех., невозвр.<br>3. Относится к сказуемому «бежал». В предложении — обстоятельство образа действия: бежал (как?) размахивая портфелем.',
  body:'1. Света читала газету, удобно (устроившись) в кресле. 2. Ребята шли по лесу, (собирая) шишки. 3. (Догнав) мяч, Серёжа ударил по воротам.',
  key:'Устроившись:<br>1. Деепричастие, обозначает добавочное действие: читала (что сделав?) устроившись. Образовано от глагола устроиться: основа инфинитива (устрои-) + суффикс -вши + -сь.<br>2. Сов. в., неперех., возвр.<br>3. Относится к сказуемому «читала». В предложении — обстоятельство (в составе оборота).<br>Собирая:<br>1. Деепричастие, обозначает добавочное действие: шли (что делая?) собирая. Образовано от глагола собирать: основа настоящего времени (собира-ют) + суффикс -я.<br>2. Несов. в., перех. (собирать что? шишки — вин. п. без предлога), невозвр.<br>3. Относится к сказуемому «шли». В предложении — обстоятельство (в составе оборота).<br>Догнав:<br>1. Деепричастие, обозначает добавочное действие: ударил (что сделав?) догнав. Образовано от глагола догнать: основа инфинитива (догна-) + суффикс -в.<br>2. Сов. в., перех. (догнать что? мяч), невозвр.<br>3. Относится к сказуемому «ударил». В предложении — обстоятельство (в составе оборота).'},
 {n:80,l:6,st:3,task:'Выполнить морфологический разбор деепричастий по плану (урок 6). Объяснить, как определена переходность каждого деепричастия.',
  obr:'См. образец в теории урока 6 (размахивая, вернувшись).',
  body:'1. Лодка, плавно (качаясь), быстро скользила по тёмным волнам. (А. С. Пушкин, «Капитанская дочка») 2. Гребцы, (держа) в руках вёсла, сидели на своих местах. (С. Т. Аксаков, «Детские годы Багрова-внука») 3. (Отвязав) лошадь, я шагом пустился домой. (М. Ю. Лермонтов, «Герой нашего времени»)',
  key:'Качаясь:<br>1. Деепричастие, обозначает добавочное действие: скользила (что делая?) качаясь. Образовано от глагола качаться: основа настоящего времени (кача-ются) + суффикс -я + -сь.<br>2. Несов. в., неперех. (с -сь переходным не бывает), возвр.<br>3. Относится к сказуемому «скользила». В предложении — обстоятельство (в составе оборота «плавно качаясь»).<br>Держа:<br>1. Деепричастие, обозначает добавочное действие: сидели (что делая?) держа. Образовано от глагола держать: основа настоящего времени (держ-ат) + суффикс -а.<br>2. Несов. в., перех. (держать что? вёсла — вин. п. без предлога), невозвр.<br>3. Относится к сказуемому «сидели». В предложении — обстоятельство (в составе оборота «держа в руках вёсла»).<br>Отвязав:<br>1. Деепричастие, обозначает добавочное действие: пустился (что сделав?) отвязав. Образовано от глагола отвязать: основа инфинитива (отвяза-) + суффикс -в.<br>2. Сов. в., перех. (отвязать что? лошадь), невозвр.<br>3. Относится к сказуемому «пустился». В предложении — обстоятельство.'},
 {n:81,l:6,st:3,task:'Распределить сочетания в два столбика: с переходными и с непереходными деепричастиями. Подчеркнуть возвратные деепричастия. Объяснить, почему возвратное деепричастие не бывает переходным.',
  obr:'Поливая васильки — перех. (поливать что? васильки); гордясь сыном — неперех., возвр.',
  body:'Открыв калитку; спускаясь с горы; махнув рукой; поправляя очки; любуясь закатом; встретив приятеля; подойдя к окну; отвернув кран; обернувшись на шум; кивая головой; нарисовав портрет; помогая няне; построив шалаш; спрятавшись за дерево; рассмешив карапуза; гуляя по парку.',
  key:'Переходные: открыв калитку, поправляя очки, встретив приятеля, отвернув кран, нарисовав портрет, построив шалаш, рассмешив карапуза — при них вин. п. без предлога.<br>Непереходные: спускаясь с горы, махнув рукой (чем?), любуясь закатом (чем?), подойдя к окну, обернувшись на шум, кивая головой (чем?), помогая няне (кому?), спрятавшись за дерево, гуляя по парку.<br>Возвратные: спускаясь, любуясь, обернувшись, спрятавшись. Постфикс -сь когда-то значил «себя» и занимает место прямого дополнения, поэтому возвратные глаголы и деепричастия переходными не бывают.'},
 {n:82,l:6,st:3,task:'Записать деепричастия, выделить суффикс деепричастия и постфикс -сь. Указать, что окончания нет (в скобках — «окончания нет, слово неизменяемое»). Распределить деепричастия по суффиксам.',
  obr:'Улыбнувшись: суффикс -вши, постфикс -сь (окончания нет).',
  body:'Мечтая, спрятав, умываясь, оглянувшись, неся, обжёгшись, придя, будучи, прислушиваясь, разбежавшись, глядя, нарисовав, сберёгши, принеся.',
  key:'-я/-а: мечтая (-я), умываясь (-я, -сь), неся (-я), придя (-я), прислушиваясь (-я, -сь), глядя (-я), принеся (-я).<br>-в: спрятав, нарисовав.<br>-вши: оглянувшись (-вши, -сь), разбежавшись (-вши, -сь).<br>-ши: обжёгшись (-ши, -сь), сберёгши.<br>-учи: будучи.<br>Ни в одном слове нет окончания: деепричастие не изменяется. Суффикс деепричастия — формообразующий.'},
 {n:83,l:6,st:3,task:'Распределить выделенные слова в четыре столбика: глаголы-сказуемые, причастия, деепричастия, наречия. Для каждого слова записать, на какой вопрос оно отвечает и изменяется ли.',
  obr:'Лиза шла по аллее, (улыбаясь). → улыбаясь — деепричастие, что делая?, не изменяется.',
  body:'1. (Пробегая) мимо, Тузик лизнул мне руку. 2. (Пробегающий) мимо Тузик лизнул мне руку. 3. Тузик (пробежал) мимо. 4. (Задумавшись), Тамара не услышала звонка. 5. (Задумавшийся) Денис не услышал звонка. 6. Тамара (задумчиво) смотрела в окно. 7. (Сияя) огнями, город встречал гостей. 8. Город, (сияющий) огнями, встречал гостей. 9. Огни города (сияли) в темноте. 10. Сынишка (громко) засмеялся.',
  key:'Глаголы: пробежал (что сделал?), сияли (что делали?) — изменяются (пробежала, сияла).<br>Причастия: пробегающий (какой?), задумавшийся (какой?), сияющий (какой?) — изменяются по родам, числам, падежам.<br>Деепричастия: пробегая (что делая?), задумавшись (что сделав?), сияя (что делая?) — не изменяются.<br>Наречия: задумчиво (как?), громко (как?) — не изменяются, вида не имеют; задумчиво образовано от прилагательного задумчивый, а не от глагола.'},
 {n:84,l:6,st:4,task:'Выполнить морфологический разбор деепричастий из стихотворных строк. Объяснить, какое действие главное и какое добавочное.',
  body:'1. Утром в путь она умчалась рано, / По лазури весело (играя). (М. Ю. Лермонтов, «Утёс») 2. Там, где горы, (убегая), / В светлой тянутся дали… (Ф. И. Тютчев) 3. Нева обратно повлеклась, / Своим любуясь возмущеньем / И (покидая) с небреженьем / Свою добычу. (А. С. Пушкин, «Медный всадник»)',
  key:'Играя:<br>1. Деепричастие, обозначает добавочное действие: умчалась (что делая?) играя. Образовано от глагола играть: основа настоящего времени (игра-ют) + суффикс -я.<br>2. Несов. в., неперех., невозвр.<br>3. Относится к сказуемому «умчалась». В предложении — обстоятельство (в составе оборота «по лазури весело играя»).<br>Убегая:<br>1. Деепричастие, обозначает добавочное действие: тянутся (что делая?) убегая. Образовано от глагола убегать: основа настоящего времени (убега-ют) + суффикс -я.<br>2. Несов. в., неперех., невозвр.<br>3. Относится к сказуемому «тянутся». В предложении — обстоятельство.<br>Покидая:<br>1. Деепричастие, обозначает добавочное действие: повлеклась (что делая?) покидая. Образовано от глагола покидать: основа настоящего времени (покида-ют) + суффикс -я.<br>2. Несов. в., перех. (покидать что? добычу — вин. п. без предлога), невозвр.<br>3. Относится к сказуемому «повлеклась». В предложении — обстоятельство (в составе оборота).'},
 {n:85,l:6,st:4,task:'Ученик выполнил морфологический разбор с ошибками. Найти и исправить все ошибки, объяснить их.',
  body:'Предложение: Улыбнувшись, учительница открыла журнал.<br>Разбор ученика: Улыбнувшись — 1. Причастие, обозначает признак предмета. Образовано от глагола улыбаться: основа настоящего времени + суффикс -вши. 2. Несов. в., перех., невозвр.; прошедшее время; окончание -сь. 3. Относится к подлежащему «учительница». В предложении — определение.',
  key:'Ошибки: 1) не причастие, а деепричастие: отвечает на вопрос «что сделав?», обозначает добавочное действие (открыла и улыбнулась); 2) образовано не от «улыбаться», а от «улыбнуться» (вид совершенный); от основы инфинитива (улыбну-), а не настоящего времени; 3) вид совершенный, а не несовершенный; 4) непереходное (возвратный глагол переходным не бывает); 5) возвратное, а не невозвратное (есть -сь); 6) времени у деепричастия нет; 7) -сь — постфикс, окончания у деепричастия нет; 8) относится к сказуемому «открыла», а не к подлежащему; 9) в предложении — обстоятельство, а не определение.<br>Верный разбор: Улыбнувшись: 1. Деепричастие, обозначает добавочное действие: открыла (что сделав?) улыбнувшись. Образовано от глагола улыбнуться: основа инфинитива (улыбну-) + суффикс -вши + -сь. 2. Сов. в., неперех., возвр. 3. Относится к сказуемому «открыла». В предложении — обстоятельство.'},
 {n:86,l:6,st:4,task:'Заполнить таблицу. От каждого глагола образовать формы, которые возможны: действительное причастие настоящего и прошедшего времени, деепричастие несовершенного и совершенного вида (совершенный вид — от глагола видовой пары). Если форма не образуется, поставить прочерк и объяснить почему.',
  body:'Строить (построить), писать (написать), читать (прочитать), бежать (убежать), улыбаться (улыбнуться), давать (дать).',
  key:'Строить: строящий, строивший; строя; построив. Писать: пишущий, писавший; — (с → ш: «пиша» не говорят); написав. Читать: читающий, читавший; читая; прочитав. Бежать: бегущий, бежавший; — (основа на г: бегут); убежав. Улыбаться: улыбающийся, улыбавшийся; улыбаясь; улыбнувшись. Давать: дающий, дававший; давая (корень да- с -ва-: от основы инфинитива); дав.<br>Причастия настоящего времени образуются от глаголов несовершенного вида; деепричастия несовершенного вида — тоже, но не от всех глаголов.'},
 {n:87,l:6,st:4,task:'Комплексное задание. 1) Переписать, расставляя запятые. 2) Над причастными оборотами написать «П», над деепричастными — «Д». 3) Выполнить морфологический разбор одного деепричастия (на выбор).',
  body:'1. Прабабушка накрыв стол чистой скатертью поставила на него горячий пирог. 2. Солнце поднявшееся над лесом осветило поляну покрытую росой. 3. Мальчики прибежавшие с реки сели обедать громко обсуждая улов. 4. Скворец усевшись на ветку берёзы растущей у дома запел свою песню. 5. Прочитав письмо полученное от Вовы Нина радостно улыбнулась.',
  key:'1. Прабабушка, накрыв стол чистой скатертью (Д), поставила на него горячий пирог. 2. Солнце, поднявшееся над лесом (П), осветило поляну, покрытую росой (П). 3. Мальчики, прибежавшие с реки (П), сели обедать, громко обсуждая улов (Д). 4. Скворец, усевшись на ветку берёзы (Д), растущей у дома (П), запел свою песню. 5. Прочитав письмо, полученное от Вовы (П), Нина радостно улыбнулась — весь деепричастный оборот (Д): «прочитав письмо, полученное от Вовы»; внутри него причастный оборот выделен запятой.<br>Образец разбора: Накрыв: 1. Деепричастие, обозначает добавочное действие: поставила (что сделав?) накрыв. Образовано от глагола накрыть: основа инфинитива (накры-) + суффикс -в. 2. Сов. в., перех. (накрыть что? стол), невозвр. 3. Относится к сказуемому «поставила». В предложении — обстоятельство.'},
 {n:88,l:6,st:4,task:'Составить алгоритм-памятку «Деепричастие: как узнать и как написать» из 6–7 шагов. Каждый шаг проверить на своём примере. Затем по своему алгоритму проверить предложения и исправить ошибки.',
  body:'Предложения для проверки: 1. Прийдя в класс, Вова недоумевая посмотрел на доску. 2. Сидя у окна, мне было скучно. 3. Ребята шли, молча, по дороге. 4. Невыучив стихотворение, Таня расстроилась.',
  key:'Примерный алгоритм: 1) Задать вопрос от сказуемого: «что делая? что сделав?» — деепричастие. 2) Определить вид: что делая? — несов. в., что сделав? — сов. в. 3) Проверить суффикс: -а/-я, -в, -вши, -ши; придя — без й; давая — с -ва-. 4) Найти зависимые слова — это оборот, выделить его запятыми. 5) Проверить, не деепричастие ли это в роли наречия (молча, лёжа…) и не фразеологизм ли (сломя голову) — тогда без запятых. 6) Проверить не: раздельно, кроме слов без пары и недо-. 7) Проверить, одно ли лицо выполняет действие деепричастия и сказуемого.<br>Проверка: 1. Придя в класс, Вова недоумевая посмотрел… → Придя в класс, Вова, недоумевая, посмотрел на доску (й не пишется; одиночное деепричастие в середине выделяется). 2. Сидя у окна, я скучал (безличное предложение). 3. Ребята шли молча по дороге (в роли наречия). 4. Не выучив стихотворение, Таня расстроилась (раздельно).'},
 {n:89,l:6,st:5,task:'Полный разбор. 1) Выполнить синтаксический разбор предложения: подчеркнуть главные члены, деепричастный оборот (одно обстоятельство), однородные дополнения и определения при них (сочетание «в хозяйской избушке» не разбирать), указать вид предложения по цели высказывания и интонации, распространённое или нераспространённое. 2) Объяснить знаки препинания. 3) Выполнить морфологический разбор деепричастия и одного причастия. 4) Выписать слова с изученными орфограммами деепричастий.',
  body:'Пройдя по двору, он заметил отворённую дверь в хозяйской избушке и видневшуюся из неё голубую рубаху. (Л. Н. Толстой, «Казаки»)',
  key:'1) Повествовательное, невосклицательное, простое, распространённое. Подлежащее — он; сказуемое — заметил; обстоятельство — пройдя по двору (деепричастный оборот); дополнения — дверь, рубаху (однородные, соединены союзом «и»); определения — отворённую, видневшуюся из неё (причастный оборот перед определяемым словом), голубую.<br>2) Запятая после «двору» — выделяется деепричастный оборот в начале предложения. Причастный оборот «видневшуюся из неё» стоит перед определяемым словом «рубаху» — не выделяется. Перед «и» между однородными дополнениями запятой нет.<br>3) Пройдя: 1. Деепричастие, обозначает добавочное действие: заметил (что сделав?) пройдя. Образовано от глагола пройти: основа будущего времени (пройд-ут) + суффикс -я. 2. Сов. в., неперех., невозвр. 3. Относится к сказуемому «заметил». В предложении — обстоятельство. Видневшуюся — причастие, н. ф. видневшийся (от глагола виднеться); постоянные признаки: действ., несов. в., прош. вр.; непостоянные: полн. ф., ед. ч., ж. р., вин. п.; в предложении — определение (в составе причастного оборота).<br>4) Пройдя — без й, суффикс -я сов. в.'},
 {n:90,l:6,st:5,task:'Тонкость. Деепричастия могут переходить в наречия и предлоги. Определить, чем является выделенное слово в каждой паре предложений: деепричастием, наречием или предлогом. Доказать: обозначает ли слово действие, есть ли зависимые слова, можно ли заменить его наречием или предлогом.',
  body:'1. (Благодаря) помощи товарища я справился с задачей. — (Благодаря) товарища за помощь, Коля крепко пожал ему руку. 2. (Лёжа) в гамаке, Гриша читал журнал. — Рыбак любит читать (лёжа). 3. (Судя) по тучам, скоро пойдёт дождь. — Судья, строго (судя) игру, не пропустил ни одного нарушения. 4. Все, (включая) малышей, пошли в поход. — (Включая) свет, тётя увидела спящего кота. 5. Тимоша (нехотя) отдал игрушку.',
  key:'1. Благодаря помощи — предлог (благодаря чему?, = из-за, с помощью); благодаря товарища — деепричастие (благодарил кого? товарища; благодарил и пожал). 2. Лёжа в гамаке — деепричастие с зависимыми словами (оборот); читать лёжа — деепричастие в роли наречия (в каком положении?). 3. Судя по тучам — вводное сочетание (по всему видно), запятые — по правилу вводных слов; судя игру — деепричастие (судил игру и не пропустил). 4. Включая малышей — предлог (= в том числе малыши); включая свет — деепричастие (включала свет и увидела). 5. Нехотя — наречие (= неохотно); деепричастия от «хотеть» нет.<br>Признаки перехода: слово перестаёт обозначать действие, не управляет словами как глагол, его можно заменить наречием или предлогом.'},
 {n:91,l:6,st:5,os:'работа с текстом',task:'Прочитать отрывок (щенок Белолобый впервые увидел волчат). 1) Выписать деепричастия, указать вид и глагол, от которого каждое образовано. 2) Объяснить запятые при обороте «увидев их» и при деепричастиях «то приседая, то подскакивая». 3) Выполнить морфологический разбор двух деепричастий разного вида. 4) Найти наречия при деепричастиях и сказуемых и доказать, что это не деепричастия. 5) Ответить: как деепричастия помогают передать поведение щенка?',
  body:'Увидев их, щенок остановился поодаль и долго смотрел на них; заметив, что они тоже внимательно смотрят на него, он стал лаять на них сердито, как на чужих. <…> Наконец щенок утомился и охрип; видя, что его не боятся и даже не обращают на него внимания, он стал несмело, то приседая, то подскакивая, подходить к волчатам. (А. П. Чехов, «Белолобый»)',
  key:'1) Увидев (сов. в., увидеть), заметив (сов. в., заметить), видя (несов. в., видеть), приседая (несов. в., приседать), подскакивая (несов. в., подскакивать).<br>2) «Увидев их» — оборот в начале предложения, запятая после него. «То приседая, то подскакивая» — однородные деепричастия с повторяющимся союзом «то… то»: между ними запятая (повторяющийся союз), а вся группа выделяется с двух сторон как одно обстоятельство.<br>3) Увидев: 1. Деепричастие, добавочное действие: остановился (что сделав?) увидев. Образовано от глагола увидеть: основа инфинитива (увиде-) + суффикс -в. 2. Сов. в., перех. (увидеть кого? их), невозвр. 3. Относится к сказуемому «остановился». Обстоятельство. Приседая: 1. Деепричастие, добавочное действие: стал подходить (что делая?) приседая. Образовано от глагола приседать: основа настоящего времени (приседа-ют) + суффикс -я. 2. Несов. в., неперех., невозвр. 3. Относится к сказуемому «стал подходить». Обстоятельство.<br>4) Поодаль, долго, сердито, несмело, внимательно — наречия: отвечают на вопросы «где? как?», не отвечают на вопрос «что делая? что сделав?», не имеют вида и суффиксов деепричастий.<br>5) Деепричастия совершенного вида (увидев, заметив) показывают, что щенок сначала замечал, а потом действовал; несовершенного (приседая, подскакивая) рисуют его неуверенное движение одновременно с главным действием — он и боится, и любопытствует.'},
 {n:92,l:6,st:4,task:'Повторение по спирали. Вставить пропущенные буквы, раскрыть скобки. Определить, причастие или деепричастие в каждом случае, и объяснить написание: суффиксы причастий, не с причастиями и деепричастиями, -сь и -ся, гласная перед -в.',
  body:'1. Колыш…щиеся на ветру флаги украшали площадь. 2. Колыхаясь на ветру, флаги шелестели. 3. (Не)замеченный нами котик спрятался в траве. 4. (Не)заметив нас, котик спрятался в траве. 5. Обид…вшись на подругу, Лена ушла. 6. Обид…вшаяся на подругу Лена ушла. 7. Стро…щийся дом виден из окна. 8. Стро… новый дом, рабочие поднимали краном плиты. 9. (Не)навид…щий ложь человек всегда говорит правду. 10. Отча…вшись дозвониться, Галя написала сообщение.',
  key:'1. Колышущиеся — причастие (колышут — I спр.: -ущ-). 2. Колыхаясь — деепричастие, -сь. 3. Не замеченный (нами) — полное причастие с зависимым словом → раздельно. 4. Не заметив — деепричастие, раздельно. 5. Обидевшись — деепричастие (обидеться). 6. Обидевшаяся — причастие (перед -вш- — та же гласная, что перед -ть), -ся. 7. Строящийся — причастие (строят — II спр.: -ящ-). 8. Строя — деепричастие (строят → строя). 9. Ненавидящий — причастие, без не не употребляется → слитно; -ящ- (ненавидят — II спр.). 10. Отчаявшись — деепричастие (отчаяться).'},
// ── Повторение
 {n:93,l:7,st:3,task:'Выписать из предложений все формы глаголов и распределить их в таблицу: «Глагол (сказуемое)», «Причастие», «Деепричастие». Для каждой формы указать вид.',
  obr:'Ветер, свистя, гнал по небу тучи. → Глагол: гнал (несов. в.); деепричастие: свистя (несов. в.).',
  body:'1. Тётка проснулась, вскочила и, не сходя с матрасика, залилась поющим лаем. (А. П. Чехов, «Каштанка») 2. Кончив молитву, бабушка молча разденется, аккуратно сложит одежду на сундук в углу и подойдёт к постели… (М. Горький, «Детство») 3. Впереди, уже далеко отделившись и звеня удаляющимся густым колокольцом, ясно виднелась на белом снегу чёрная тройка Захара. (Л. Н. Толстой, «Война и мир»)',
  key:'Глаголы: проснулась, вскочила, залилась (сов. в.); разденется, сложит, подойдёт (сов. в.); виднелась (несов. в.).<br>Причастия: поющим (несов. в.), удаляющимся (несов. в.).<br>Деепричастия: не сходя (несов. в.), кончив (сов. в.), отделившись (сов. в.), звеня (несов. в.); «молча» в таблицу не входит: это деепричастие в роли наречия.'},
 {n:94,l:7,st:4,task:'Комплексное упражнение. Переписать, вставляя буквы, раскрывая скобки и расставляя запятые. Подчеркнуть деепричастные обороты как обстоятельства. Указать, в каких предложениях деепричастие употреблено с ошибкой, и исправить их.',
  body:'1. При(й)дя с катка Стёпа (не)раздеваясь сел за компьютер. 2. Котёнок спал на подоконнике свернувш… клубком. 3. (Не)смотря под ноги Геня споткнулся о камень. 4. Выйдя на лёд у меня сразу развязался шнурок. 5. Ребята катались (не)обращая внимания на мороз и весело перекликаясь. 6. Зате…в игру в снежки мы забыли о времени. 7. Соня (не)хотя пошла в город всё время оглядываясь на каток. 8. Вернувшись с катка нас напоили горячим чаем.',
  key:'1. Придя с катка, Стёпа, не раздеваясь, сел за компьютер. 2. Котёнок спал на подоконнике, свернувшись клубком. 3. Не смотря под ноги, Геня споткнулся о камень (= не глядя — деепричастие, раздельно). 4. Ошибка (разные лица): Когда я вышел на лёд, у меня сразу развязался шнурок. 5. Ребята катались, не обращая внимания на мороз и весело перекликаясь. 6. Затеяв игру в снежки, мы забыли о времени. 7. Соня нехотя пошла в город, всё время оглядываясь на каток (нехотя — наречие, слитно). 8. Ошибка (разные лица: вернулись мы, а напоили другие): Когда мы вернулись с катка, нас напоили горячим чаем.'},
 {n:95,l:7,st:4,task:'Задание в формате ОГЭ. Прочитать текст. 1) Среди предложений 1–6 найти предложения с обособленным обстоятельством, выраженным деепричастным оборотом; записать их номера. 2) Из предложения 4 выписать деепричастие, перешедшее в роль наречия. 3) Из предложения 6 выписать деепричастие совершенного вида с суффиксом -я. 4) Найти предложение, в котором деепричастный оборот стоит после союза «и».',
  body:'(1) Ранним утром мы вышли из дома. (2) Ещё не проснувшиеся улицы были пусты. (3) Свернув к реке, мы пошли по тропинке вдоль берега. (4) Пасечник шёл молча, а я то и дело останавливался. (5) Солнце поднялось над рекой и, пробившись сквозь туман, осветило противоположный берег. (6) Придя к старой иве, мы сели на поваленное дерево отдохнуть.',
  key:'1) 3, 5, 6. Предложение 2 — причастный оборот («не проснувшиеся» перед определяемым словом, не выделяется).<br>2) Молча.<br>3) Придя.<br>4) Предложение 5: «и, пробившись сквозь туман, …».'},
 {n:96,l:7,st:4,task:'Задание в формате итогового теста. Выписать номера сочетаний, в которых не пишется слитно. Раскрыть скобки во всех сочетаниях и указать часть речи (глагол, причастие, деепричастие, предлог, наречие).',
  body:'1) (не)навидя скуку; 2) (не)дочитав книгу; 3) (не)досыпая перед экзаменом; 4) (не)решённая до сих пор задача; 5) (не)смотря на ветер; 6) (не)законченный рисунок; 7) (не)смотря по сторонам; 8) (не)хотя встать; 9) (не)забыв о просьбе; 10) работа (не)закончена; 11) (не)доумевающий взгляд; 12) (не)заметил ошибку.',
  key:'Слитно: 1 (ненавидя — деепр., без не не употр.), 3 (недосыпая — деепр. с недо-), 5 (несмотря на — предлог), 6 (незаконченный — полное прич. без зав. слов), 8 (нехотя — наречие), 11 (недоумевающий — прич., без не не употр.).<br>Раздельно: 2 (не дочитав — деепр.), 4 (не решённая до сих пор — прич. с зав. словами), 7 (не смотря — деепр. = не глядя), 9 (не забыв — деепр.), 10 (не закончена — краткое прич.), 12 (не заметил — глагол).'},
 {n:97,l:7,st:5,os:'изложение',task:'Изложение с грамматическим заданием. Прослушать (прочитать) текст дважды и пересказать его письменно, близко к тексту. Условие: в изложении сохранить не меньше пяти деепричастных оборотов и добавить два своих. Деепричастия подчеркнуть, над ними указать вид. После написания проверить каждый оборот: одно ли лицо выполняет оба действия, верно ли поставлены запятые.',
  body:'Скворечник. Весной мы с Рустамом решили сделать скворечник. Найдя в сарае старые доски, мы принесли их во двор. Рустам, вооружившись пилой, отпиливал стенки, а я, придерживая доску, следил, чтобы линия была ровной. Собрав домик и прибив к нему крышу, мы долго думали, где его повесить. Наконец, посоветовавшись с дедом, выбрали высокую берёзу у забора. Дед, приставив лестницу, сам забрался наверх и, крепко привязав скворечник проволокой, спустился вниз. Через неделю мы увидели, как скворец, держа в клюве травинку, деловито залетел в новый дом. Глядя на него, мы радовались, словно сами получили подарок.',
  key:'Критерии: содержание передано полно и последовательно; сохранено не меньше пяти оборотов текста (найдя в сарае старые доски; вооружившись пилой; придерживая доску; собрав домик и прибив к нему крышу; посоветовавшись с дедом; приставив лестницу; крепко привязав скворечник проволокой; держа в клюве травинку; глядя на него); добавлено два своих верных оборота; вид указан верно (несов. в.: придерживая, держа, глядя; остальные — сов. в.); нет ошибок «разные лица»; запятые при оборотах, в том числе после «и» (и, крепко привязав…).'},
 {n:98,l:7,st:5,os:'диктант',task:'Контрольный диктант с грамматическими заданиями. 1) Записать текст, вставляя буквы, раскрывая скобки и расставляя запятые. 2) Выполнить морфологический разбор деепричастий «оглядываясь» и «спрятав». 3) Выписать два деепричастия с не и объяснить написание. 4) Найти деепричастие в роли наречия.',
  body:'Белка. Однажды гуляя по осеннему лесу я увидел белку. Она сидела на ветке высокой ели держ… в лапках шишку и старательно выбирала из неё семена. Заметив меня зверёк замер и (не)сводя с меня глаз прижался к стволу. Я застыл (не)смея пошевелиться. Успокоившись белка снова принялась за шишку. Покончив с ней она спустилась пониже и оглядываясь на меня перепрыгнула на соседнюю сосну. Там спрятав в дупле орех она распушила хвост и исчезла в густых ветвях. Я ещё долго молча стоял под елью прислушиваясь к шорохам леса.',
  key:'Однажды, гуляя по осеннему лесу, я увидел белку. Она сидела на ветке высокой ели, держа в лапках шишку, и старательно выбирала из неё семена. Заметив меня, зверёк замер и, не сводя с меня глаз, прижался к стволу. Я застыл, не смея пошевелиться. Успокоившись, белка снова принялась за шишку. Покончив с ней, она спустилась пониже и, оглядываясь на меня, перепрыгнула на соседнюю сосну. Там, спрятав в дупле орех, она распушила хвост и исчезла в густых ветвях. Я ещё долго молча стоял под елью, прислушиваясь к шорохам леса.<br>2) Оглядываясь: 1. Деепричастие, добавочное действие: перепрыгнула (что делая?) оглядываясь. Образовано от глагола оглядываться: основа настоящего времени (оглядыва-ются) + суффикс -я + -сь. 2. Несов. в., неперех., возвр. 3. Относится к сказуемому «перепрыгнула». Обстоятельство (в составе оборота). Спрятав: 1. Деепричастие, добавочное действие: распушила (что сделав?) спрятав. Образовано от глагола спрятать: основа инфинитива (спрята-) + суффикс -в. 2. Сов. в., перех. (спрятать что? орех), невозвр. 3. Относится к сказуемому «распушила». Обстоятельство.<br>3) Не сводя, не смея — раздельно: деепричастия употребляются без не.<br>4) Молча (молча стоял).'},
 {n:99,l:7,st:5,os:'сочинение',task:'Сочинение-рассуждение на лингвистическую тему (по типу ОГЭ). Объяснить, зачем в языке нужны деепричастия, и доказать свою мысль двумя примерами из упражнений этой главы (указать номер упражнения и предложения). Объём — 70–90 слов. План: тезис — два аргумента с примерами — вывод.',
  body:'Опорные мысли: деепричастие делает одно действие главным, другое — добавочным; позволяет коротко сказать то, что иначе потребовало бы придаточной части; помогает писателю нарисовать движение; вид деепричастия показывает порядок действий.',
  key:'Критерии: есть тезис; два аргумента с верными примерами и ссылками на упражнения; вывод; 70–90 слов; нет речевых и грамматических ошибок с деепричастиями.<br>Образец: Деепричастие — особая форма глагола, которая позволяет показать в одном предложении главное и добавочное действие. Например, у Пушкина «Буря мглою небо кроет, / Вихри снежные крутя» (упражнение 8): главное — кроет, а крутя только дополняет картину. Кроме того, деепричастие помогает говорить короче: вместо «Когда Костя вернулся в посёлок, он сел ужинать» можно сказать «Вернувшись в посёлок, Костя сел ужинать» (упражнение 67). Таким образом, деепричастия делают речь точной, сжатой и выразительной.'},
 {n:100,l:7,st:5,os:'работа с текстом',task:'Комплексный анализ текста. 1) Выписать деепричастия и деепричастные обороты; указать вид каждого деепричастия. 2) Объяснить запятые при деепричастиях (в том числе после «и»). 3) Деепричастие в роли наречия есть в предложении, которое у Горького стоит перед этим отрывком (упражнение 93: «Кончив молитву, бабушка молча разденется…»). Найти его и объяснить, почему оно не выделяется запятыми. 4) Выполнить морфологический разбор деепричастия «перевернувшись». 5) Как деепричастия помогают автору показать игру бабушки и внука?',
  body:'Предвкушая дальнейшее, я не могу сдержать улыбки; тогда она рычит: — А-а, так ты над бабушкой-старухой шутки шутить затеял! Взяв одеяло за край, она так ловко и сильно дёргает его к себе, что я подскакиваю в воздухе и, несколько раз перевернувшись, шлёпаюсь в мягкую перину, а она хохочет… (М. Горький, «Детство»)<br>Пояснения: предвкушать — заранее радоваться тому, что будет; перина — мягкий тюфяк, набитый пухом.',
  key:'1) Предвкушая дальнейшее (несов. в.); взяв одеяло за край (сов. в.); несколько раз перевернувшись (сов. в.).<br>2) «Предвкушая дальнейшее», «Взяв одеяло за край» — обороты в начале предложения, запятая после них. «И, несколько раз перевернувшись, шлёпаюсь» — «и» соединяет сказуемые «подскакиваю» и «шлёпаюсь», оборот относится ко второму и выделяется с двух сторон, запятая после «и».<br>3) «Молча» (молча разденется) — деепричастие в роли наречия: стоит прямо при сказуемом, обозначает образ действия (= безмолвно), запятыми не выделяется.<br>4) Перевернувшись: 1. Деепричастие, добавочное действие: шлёпаюсь (что сделав?) перевернувшись. Образовано от глагола перевернуться: основа инфинитива (переверну-) + суффикс -вши + -сь. 2. Сов. в., неперех., возвр. 3. Относится к сказуемому «шлёпаюсь». Обстоятельство (в составе оборота).<br>5) Деепричастия совершенного вида (взяв, перевернувшись) показывают быструю смену действий — бабушка схватила одеяло, Олег перевернулся и упал; несовершенный вид (предвкушая) передаёт ожидание, которое длится. Сцена получается живой и весёлой.'}
];
const DR_LNAMES=['',...DR.lessons.map(l=>l.t),'Повторение'];
const DR_BOOKREF={2:'Розенталь, «Русский язык» (пособие), упр. 251–252',3:'Розенталь, «Русский язык» (пособие), § 75, упр. 390–392',5:'Розенталь, «Русский язык» (пособие), § 101, упр. 500–501; упр. 393'};
